.ph-e{background:linear-gradient(160deg,#e8590c,#ffa94d)}
.ph-f{background:linear-gradient(160deg,#c92a2a,#ff8787)}
.ph-l{background:rgba(16,18,43,.72);color:#fff;padding:.18em .7em;border-radius:999px;line-height:1.3;font-size:max(.78em,12px)}

/* G01 · גלילה צידית מוצמדת */
/* בלי GSAP ובהפחתת תנועה הרצועה נגללת לצד ביד. החיתוך, הגובה והמירכוז רק כשהמהלך רץ */
.wrapper{transition:all 0s !important;overflow-x:auto;background:var(--bg, #f7f7fa)}
.wrapper.gsap-live{overflow:hidden;height:100vh;display:flex;align-items:center}
.scroll{flex:none;display:flex;gap:24px;width:max-content;padding:80px var(--gutter, clamp(24px, 5vw, 96px))}
.scroll .ph{flex:0 0 clamp(300px,26vw,460px);height:clamp(240px,20vw,360px);font-size:22px}

