/* G07 · תמונות רודפות עכבר (Image Trail) */
.tzone{height:60vh;border:2px dashed #ccc;border-radius:var(--r, 14px);display:flex;align-items:center;justify-content:center;margin-inline:var(--gutter, clamp(24px, 5vw, 96px));color:var(--muted, #6a6d85)}
