    gsap.fromTo(el,{textContent:0},{textContent:+el.dataset.count,snap:{textContent:1},ease:"none",
      scrollTrigger:{trigger:el,start:"clamp(top 85%)",end:"clamp(top 40%)",scrub:true,
        onRefresh:s=>{if(s.end-s.start<1)s.animation.progress(1)}}});
