      [...text].forEach((c,i)=>{
        const s=document.createElement("span");
        s.className="rb-ch";
        s.style.setProperty("--i",i);
        s.textContent=c===" "?"\u00a0":c;
        row.appendChild(s);
      });
      el.appendChild(row);
    });
  });
})();

