.hd-frame{position:relative;height:clamp(420px,76vh,640px);overflow-y:auto;overscroll-behavior:contain;
  border:1px solid var(--line, #e4e4ee);border-radius:var(--r, 14px);margin-inline:var(--gutter, clamp(24px, 5vw, 96px));background:var(--bg, #f7f7fa)}
