(function(){
  const items=[...document.querySelectorAll(".mm-item")];
  const hoverable=matchMedia("(hover:hover)");
  let timer=null,clicked=false;
  function open(it){
    items.forEach(o=>{o.classList.toggle("open",o===it);o.querySelector(".mm-btn").setAttribute("aria-expanded",String(o===it));});
  }
  function closeAll(){open(null);clicked=false;}
  items.forEach(it=>{
    const btn=it.querySelector(".mm-btn");
    // לחיצה על פאנל שההובר פתח לא סוגרת אותו: מי שרגיל ללחוץ על פריט תפריט היה רואה
    // אותו נפתח ונסגר. הלחיצה הראשונה "מאשרת" את הפתיחה, והשנייה סוגרת.
    btn.addEventListener("click",e=>{e.preventDefault();
      if(it.classList.contains("open")&&clicked)closeAll();else{open(it);clicked=true;}});
    // השהיה קטנה ביציאה, אחרת המסלול מהכפתור אל הפאנל סוגר אותו באמצע.
    // pointerType מסנן מגע: שם הפתיחה היא בלחיצה בלבד.
    it.addEventListener("pointerenter",e=>{if(e.pointerType!=="mouse"||!hoverable.matches)return;
      clearTimeout(timer);if(!it.classList.contains("open")){open(it);clicked=false;}});
    it.addEventListener("pointerleave",e=>{if(e.pointerType!=="mouse"||!hoverable.matches)return;
      clearTimeout(timer);timer=setTimeout(closeAll,180);});
    // פוקוס שיצא מהפריט (Tab לפריט הבא) סוגר את הפאנל שלו
    it.addEventListener("focusout",e=>{if(!it.contains(e.relatedTarget)&&it.classList.contains("open")&&!it.matches(":hover"))closeAll();});
  });
  addEventListener("keydown",e=>{
    if(e.key!=="Escape")return;
    // Escape מתוך הפאנל מחזיר את הפוקוס לכפתור שפתח אותו, ולא מפיל אותו לראש העמוד
    const cur=items.find(o=>o.classList.contains("open"));
    if(cur&&cur.contains(document.activeElement))cur.querySelector(".mm-btn").focus();
    closeAll();
  });
  addEventListener("click",e=>{if(!e.target.closest(".mm-item"))closeAll();});
})();

