  mask-image:linear-gradient(90deg,transparent 96px,#000 calc(96px + 6vw),#000 calc(100% - 96px - 6vw),transparent calc(100% - 96px))}
/* ההזזה היא רוחב קבוצה מדויק בפיקסלים, ומספר העותקים נגזר מרוחב המסך */
