(function(){
  const links=[...document.querySelectorAll(".pt-nav a")];
  const view=document.querySelector("#pt-view");
  const rm=matchMedia("(prefers-reduced-motion: reduce)");
  const G=typeof gsap!=="undefined";
  const bars=G?gsap.utils.toArray(".pt-curtain i"):[],label=document.querySelector(".pt-label");
  const D=.5;
  let busy=false;
  function cover(text){
    label.textContent=text;                      // קודם הטקסט, אחר כך החשיפה. אחרת רואים לרגע את השם הקודם
    return gsap.timeline()
      .to(bars,{yPercent:-101,duration:D,ease:"power3.inOut",stagger:.05})
      .to(label,{opacity:1,duration:D*.5},"-="+D*.5);
  }
  function reveal(){
    return gsap.timeline()
      .to(label,{opacity:0,duration:D*.4})
      .to(bars,{yPercent:-202,duration:D,ease:"power3.inOut",stagger:.05},"-="+D*.2)
      .set(bars,{yPercent:101});     // מחזירים למטה בלי אנימציה, מוכנים למעבר הבא
  }
  links.forEach(a=>{
    a.addEventListener("click",e=>{
      e.preventDefault();
      // לחיצה נוספת באמצע מעבר לא בונה וילון שני שמתחרה על אותן רצועות
      if(busy||a.classList.contains("on"))return;
      links.forEach(x=>{x.classList.toggle("on",x===a);if(x===a)x.setAttribute("aria-current","page");else x.removeAttribute("aria-current");});
      // בהפחתת תנועה (וכש-GSAP לא נטען) התוכן מתחלף מיד, בלי וילון ובלי הבהוב של רצועות
      if(!G||rm.matches){view.querySelector("h3").textContent=a.dataset.t;return;}
      busy=true;
      gsap.timeline()
        .add(cover(a.dataset.t))
        // כאן, מתחת לוילון, מחליפים תוכן. באתר אמיתי: location.href=a.href
        .add(()=>{view.querySelector("h3").textContent=a.dataset.t;scrollTo(0,0);})
        .add(reveal())
        .add(()=>{busy=false;});
    });
  });
  if(G)gsap.set(bars,{yPercent:101});
})();

