/* G72 · סקשן שמתהפך בין שתי פאות בגלילה */
/* בלי GSAP או בהפחתת תנועה: שתי הפאות זו מתחת לזו, כל אחת קריאה.
   הבמה וההיפוך יושבים תחת .mv-on, שהסקריפט מוסיף רק כשהתנועה מותרת */
.fl-stage{display:grid;place-items:center;padding:var(--sec, clamp(120px, 12vw, 260px)) var(--gutter, clamp(24px, 5vw, 96px))}
.fl-card{position:relative;width:min(880px,92vw);display:grid;gap:16px}
.fl-face{position:relative;aspect-ratio:16/10;border-radius:22px;overflow:hidden;isolation:isolate;
  display:grid;place-items:center;text-align:center;padding:clamp(20px,4vw,50px);color:#fff}
.fl-face h3{margin:0;font-size:clamp(24px,3.6vw,48px);line-height:1.14;max-width:20ch}
