.fl-face .ph{position:absolute;inset:0;border-radius:0;font-size:0;z-index:-1}
.fl-cap{display:none;position:absolute;bottom:7vh;inset-inline:0;text-align:center;color:var(--muted, #6a6d85);font-size:15px}
/* הבמה */
.fl.mv-on{height:250vh;position:relative}
.fl.mv-on .fl-stage{position:sticky;top:0;height:100vh;perspective:1600px;padding-block:0}
.fl.mv-on .fl-card{display:block;aspect-ratio:16/10;transform-style:preserve-3d;will-change:transform}
.fl.mv-on .fl-face{position:absolute;inset:0;isolation:auto;backface-visibility:hidden}
.fl.mv-on .fl-back{transform:rotateY(180deg)}
.fl.mv-on .fl-cap{display:block}

