if (typeof gsap !== "undefined") gsap.registerPlugin(ScrollTrigger);

(function(){
  if(typeof gsap==="undefined")return;   // בלי הספרייה שתי הפאות עומדות זו מתחת לזו
  const root=document.querySelector(".fl"),card=root.querySelector(".fl-card");
  // הבמה נדלקת רק כשהתנועה מותרת. בהפחתת תנועה הפאה האחורית לא מסתתרת מאחורי backface, אלא עומדת מתחת לקדמית
  gsap.matchMedia().add("(prefers-reduced-motion: no-preference)",()=>{
    root.classList.add("mv-on");
    gsap.timeline({scrollTrigger:{trigger:root,start:"top top",end:"bottom bottom",scrub:.6}})
      // משך מפורש לשניהם, אחרת ההיפוך נגמר בחצי הדרך והשאר ריק
      .fromTo(card,{rotateY:0},{rotateY:180,duration:1,ease:"none"},0)
      // התכווצות קלה באמצע ההיפוך: בלעדיה הקלף נראה שטוח בדיוק ברגע שהוא הכי דק
      .fromTo(card,{scale:1},{scale:.9,ease:"none",yoyo:true,repeat:1,duration:.5},0);
    return ()=>root.classList.remove("mv-on");
  });
})();

