.q .hd-in{display:flex;align-items:center;gap:24px;max-width:1320px;height:80px;margin-inline:auto;padding-inline:var(--gut)}
.q .logo{display:inline-flex;align-items:center;gap:10px;min-height:44px;white-space:nowrap;font-size:22px;font-weight:600;line-height:1;color:var(--ink, #16182b)}
