.q .rv:nth-child(2) figcaption span,.q .rv:nth-child(2) .rv-t{color:var(--ink, #16182b)}
/* אינדקס העבודות: רגע החתימה */
.q .idx{--pvw:400px;position:relative;padding-inline-end:calc(var(--pvw) + 72px);min-height:760px}
.q .idx-list{display:flex;flex-direction:column;gap:8px}
.q .idx-b{display:grid;grid-template-columns:minmax(0,1fr) 24px;align-items:center;gap:20px;width:100%;min-height:96px;padding:20px 24px;border:0;border-radius:0;background:var(--paper-2);color:var(--ink, #16182b);font:inherit;text-align:start;cursor:pointer;transition:background-color .18s var(--ease),color .18s var(--ease)}
