entries.css:
/* S09 · Soft Modern */
@font-face{font-family:"MV Google Sans";src:url("https://liavwebdesign-spec.github.io/motion-vault/assets/fonts/google-sans.woff2") format("woff2");font-weight:400 700;font-display:swap}
.cwrap{container-type:inline-size}
.q{--bg:#EEF0F6;--surface:#fff;--surface-2:#F4F5F9;--surface-2-hv:#E7E9F2;
 --ink:#131A2B;--ink-2:#1C2540;--ink-hv:#26304D;--muted:#5A6274;--muted-on-ink:#B6BDD0;--ph:#656D80;
 --accent:#C63C18;--accent-2:#AD3212;--accent-hi:#E0562A;--accent-soft:color-mix(in srgb,var(--accent, #4a3aff) 11%,#fff);
 --grad:linear-gradient(135deg,#A82F0E 0%,#BC3815 52%,#C84018 100%);--err:#B42318;
 --r-page:28px;--r-card:20px;--r-inner:14px;--r-chip:12px;--r-pill:999px;
 --sh-card:0 2px 8px rgba(19,26,43,.04),0 12px 32px rgba(19,26,43,.06);
 --sh-lift:0 4px 12px rgba(19,26,43,.06),0 24px 48px rgba(19,26,43,.10);
 --ease:cubic-bezier(.2,.6,.2,1);
 --gut:clamp(20px,3.75cqi,96px);--sm:clamp(12px,1.25cqi,24px);
 --sec:clamp(64px,7.5cqi,160px);--sec-loose:clamp(88px,8.75cqi,192px);
 --pad:clamp(24px,2.5cqi,48px);--gap:clamp(16px,1.875cqi,32px);--gap-l:clamp(32px,5cqi,96px);--head-gap:clamp(40px,4.375cqi,88px);--ov:clamp(40px,5cqi,112px);
 --fs-h1:clamp(36px,min(4.4cqi,7.8svh),104px);--fs-h2:clamp(28px,2.9cqi,72px);--fs-xl:clamp(34px,4.4cqi,96px);--fs-h3:clamp(20px,1.7cqi,34px);
 --fs-lead:clamp(18px,.9cqi + 8px,28px);--fs-body:clamp(16px,.35cqi + 12px,21px);--fs-ui:clamp(15px,.2cqi + 12.5px,18px);
 --fs-num:clamp(48px,4.4cqi,112px);--fs-price:clamp(44px,3.75cqi,88px);
 background:var(--bg, #f7f7fa);color:var(--ink, #16182b);font-family:"MV Google Sans",system-ui,sans-serif;font-size:var(--fs-body, clamp(17px, 0.6vw + 0.7rem, 22px));font-weight:400;line-height:1.65;
 overflow:clip;position:relative;isolation:isolate;-webkit-font-smoothing:antialiased}
.q *{box-sizing:border-box}
.q h1,.q h2,.q h3,.q p,.q ul,.q ol{margin:0}
.q ul,.q ol{list-style:none;padding:0}
.q a{color:inherit;text-decoration:none}
.q img{display:block;max-width:100%}
.q :focus-visible{outline:3px solid var(--accent, #4a3aff);outline-offset:3px}
.q h1,.q h2,.q h3{text-wrap:balance;font-weight:700}
.q p{text-wrap:pretty}
.q section[id]{scroll-margin-top:calc(var(--vt,0px) + 88px)}
.q h1{font-size:var(--fs-h1, clamp(26px, 1.6vw + 0.5rem, 40px));line-height:1.1;letter-spacing:-.015em}
.q h1 em{font-style:normal;color:var(--accent, #4a3aff)}
.q h2{font-size:var(--fs-h2, clamp(28px, 1.9vw + 0.5rem, 52px));line-height:1.15}
.q h3{font-size:var(--fs-h3);line-height:1.25}
.q .lead{font-size:var(--fs-lead);line-height:1.55;color:var(--muted, #6a6d85);max-width:62ch}
.q .body{color:var(--muted, #6a6d85);max-width:62ch}
.q .skip{position:absolute;inset-inline-start:16px;top:-80px;z-index:60;display:inline-flex;align-items:center;min-height:44px;padding:0 20px;border-radius:var(--r-pill);background:var(--ink, #16182b);color:#fff;font-weight:500}
.q .skip:focus{top:16px}
.q .ico{width:20px;height:20px;stroke:currentColor;fill:none;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;flex:none;display:block}
/* eyebrow: אחד לכל העמוד */
.q .eyebrow{display:inline-flex;align-items:center;gap:8px;height:32px;padding:0 16px;border-radius:var(--r-pill);background:#fff;font-size:var(--fs-ui);font-weight:500;line-height:1;color:var(--ink, #16182b)}
.q .eyebrow i{width:8px;height:8px;border-radius:50%;background:var(--accent, #4a3aff);flex:none}
.q :is(.slab,.conv-card) .eyebrow{background:var(--surface-2)}
/* כפתורים: שלוש רמות, ארבעה מצבים. הבאדג' העגול בקצה החץ הוא החתימה */
.q .btn{display:inline-flex;align-items:center;gap:16px;min-height:56px;padding:8px;padding-inline-start:28px;border:0;border-radius:var(--r-pill);background:var(--accent, #4a3aff);color:#fff;font:inherit;font-size:var(--fs-ui);font-weight:700;line-height:1;white-space:nowrap;cursor:pointer;
 transition:background-color .18s var(--ease),box-shadow .18s var(--ease),transform .12s var(--ease)}
.q .btn .bd{display:grid;place-items:center;width:40px;height:40px;border-radius:50%;background:#fff;color:var(--accent, #4a3aff);flex:none;transition:transform .3s var(--ease),background-color .18s var(--ease),color .18s var(--ease)}
.q .btn:active{transform:scale(.98)}
.q .btn:focus-visible{outline:3px solid var(--accent, #4a3aff);outline-offset:3px}
.q .btn.sm{min-height:48px;gap:12px;padding-inline-start:20px}
