.q .lnk:hover{color:var(--copper-t);text-decoration-color:var(--copper-t)}
.q .lnk:hover .ico{transform:translateX(-4px)}
}
/* שדות: חמישה מצבים */
.q .fld{display:flex;flex-direction:column;gap:8px}
