.q .in{font:inherit;font-size:16px;line-height:1.2;min-height:52px;padding:14px 20px;border:1.5px solid var(--field);border-radius:999px;background:var(--paper);color:var(--ink, #16182b);appearance:none;width:100%;transition:border-color .15s var(--ease),box-shadow .15s var(--ease)}
