.q .hd nav a{display:inline-flex;align-items:center;min-height:44px;padding:10px 16px;border-radius:999px;font-size:14px;font-weight:500;line-height:1;color:var(--muted, #6a6d85);transition:background .15s var(--ease),color .15s var(--ease)}
