/* מספרים ומחירים: פונט התצוגה, נחושת */
.q .price{font-family:var(--disp);font-size:30px;line-height:1;font-variant-numeric:lining-nums tabular-nums;white-space:nowrap}
/* רגע החתימה: מניפת העונה על שיש אדום */
.q .marble{position:relative;background:var(--marble);color:var(--on-ox);padding:calc(var(--sec, clamp(120px, 12vw, 260px)) + 48px) var(--gut) calc(var(--sec, clamp(120px, 12vw, 260px)) + 48px);clip-path:polygon(0 0,100% 0,100% calc(100% - 48px),58% calc(100% - 48px),58% calc(100% - 32px),55% calc(100% - 32px),55% calc(100% - 16px),52% calc(100% - 16px),52% 100%,48% 100%,48% calc(100% - 16px),45% calc(100% - 16px),45% calc(100% - 32px),42% calc(100% - 32px),42% calc(100% - 48px),0 calc(100% - 48px))}
.q .marble::before{content:"";position:absolute;inset:0;background:radial-gradient(ellipse 70% 60% at 50% 55%,rgba(30,8,8,.55),rgba(30,8,8,.2) 70%,transparent);pointer-events:none}
