entries.css:
/* S05 · מינימליזם עריכתי */
/* Google Sans בגודל האמיתי שלו. המאגר מגיש "Google Sans" עם size-adjust של 80% (הממשק שלו כויל לפלוני),
   ולכן העור טוען את אותו קובץ בשם משלו. בפרויקט מוחקים את השורה הזו וטוענים Google Sans כרגיל (library/fonts.md). */
@font-face{font-family:"MV Google Sans";src:url("https://liavwebdesign-spec.github.io/motion-vault/assets/fonts/google-sans.woff2") format("woff2");font-weight:400 700;font-display:swap}
.cwrap{container-type:inline-size}
.q{--accent:#4A6EF6;--accent-text:#3552D8;--btn-solid:#3B5BDB;--tint-12:color-mix(in srgb,var(--accent, #4a3aff) 12%,#fff);--tint-4:color-mix(in srgb,var(--accent, #4a3aff) 4%,#fff);
 --ink:#111;--muted:#6b7280;--muted-strong:#4b5563;--border:#eaeaea;--border-2:#e5e7eb;--surface:#fff;--surface-muted:#f3f4f6;--err:#d92d20;
 --r-control:12px;--r-card:16px;--ease:cubic-bezier(.2,.6,.2,1);--shadow-soft:0 6px 20px rgba(17,24,39,.08);--shadow-shot:0 30px 60px rgba(17,24,39,.16);
 --sec:112px;--gut:clamp(20px,4cqi,64px);
 background:var(--surface);color:var(--ink, #16182b);font-family:"MV Google Sans","Google Sans",system-ui,sans-serif;font-size:15px;line-height:1.68;overflow:clip;position:relative;isolation:isolate;-webkit-font-smoothing:antialiased}
.q *{box-sizing:border-box}
.q h1,.q h2,.q h3,.q p,.q ul{margin:0}
.q a{color:inherit;text-decoration:none}
.q ul{list-style:none;padding:0}
.q h1{font-size:45px;line-height:1.13;font-weight:600;letter-spacing:-.01em}
.q h2{font-size:32px;line-height:1.21;font-weight:600}
.q h3{font-size:19px;line-height:1.37;font-weight:600}
.q .lead{font-size:17px;line-height:1.58;color:var(--muted, #6a6d85);max-width:640px}
.q .body{font-size:15px;line-height:1.68;color:var(--muted, #6a6d85);max-width:640px}
.q .meta{font-size:13px;font-weight:500;line-height:1.2;color:var(--muted, #6a6d85)}
.q .micro{font-size:12px;line-height:1.2;color:var(--muted, #6a6d85)}
.q .eyebrow{display:inline-flex;align-items:center;gap:8px;font-size:12px;font-weight:600;line-height:1;color:var(--accent-text);background:var(--tint-12);padding:7px 12px;border-radius:var(--r-control)}
.q .eyebrow i{width:6px;height:6px;border-radius:50%;background:var(--accent, #4a3aff);margin-top:1px}
.q .hl{font-size:12px;font-weight:500;color:var(--accent-text);margin-top:16px}
.q .muted-bg .body,.q .muted-bg .lead,.q .muted-bg .micro,.q .muted-bg .meta{color:var(--muted-strong)}
.q .ico{width:24px;height:24px;stroke:currentColor;fill:none;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;color:var(--accent, #4a3aff);flex:none;display:block}
.q .ico.s{width:20px;height:20px}
/* כפתורים: שלוש רמות, ארבעה מצבים */
.q .btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;font:inherit;font-size:14px;font-weight:500;line-height:1;border-radius:var(--r-control);padding:13px 24px 14px;min-height:44px;border:1px solid transparent;cursor:pointer;background:var(--btn-solid);color:#fff;transition:background .18s var(--ease),border-color .18s var(--ease),color .18s var(--ease),transform .12s var(--ease),box-shadow .18s var(--ease)}
.q .btn:hover,.q .btn.is-hover{background:color-mix(in srgb,var(--btn-solid) 88%,#000)}
.q .btn:active,.q .btn.is-active{transform:scale(.98)}
.q .btn:focus-visible,.q .btn.is-focus{outline:0;box-shadow:0 0 0 3px color-mix(in srgb,var(--accent, #4a3aff) 35%,transparent)}
.q .btn.is-disabled,.q .btn:disabled{opacity:.5;pointer-events:none}
.q .btn.lg{font-size:16px;padding:15px 28px 16px;min-height:50px}
.q .btn.sm{font-size:13px;padding:9px 18px 10px;min-height:38px}
.q .btn.b2{background:var(--surface);color:var(--ink, #16182b);border-color:var(--border-2)}
.q .btn.b2:hover,.q .btn.b2.is-hover{background:#f9fafb;border-color:#d1d5db}
.q .lnk{display:inline-flex;align-items:center;gap:6px;font-size:13px;font-weight:500;color:var(--ink, #16182b);padding:4px 0;border-bottom:1px solid transparent;transition:color .18s var(--ease),border-color .18s var(--ease),gap .18s var(--ease)}
.q .lnk .ico{color:var(--accent, #4a3aff);width:20px;height:20px;transition:transform .18s var(--ease)}
.q .lnk:hover,.q .lnk.is-hover{color:var(--accent-text);border-color:var(--accent-text)}
.q .lnk:hover .ico,.q .lnk.is-hover .ico{transform:translateX(-3px)}
.q .lnk:focus-visible{outline:0;box-shadow:0 0 0 3px color-mix(in srgb,var(--accent, #4a3aff) 35%,transparent);border-radius:4px}
/* על רצועת ה-CTA (ברקע btn-solid: לבן על accent נותן 4.3 ונופל מ-AA) */
.q :is(.band,.band-x) .btn{background:#fff;color:var(--accent-text)}
.q :is(.band,.band-x) .btn:hover{background:#eef1ff}
.q :is(.band,.band-x) .btn.b2{background:transparent;color:#fff;border-color:rgba(255,255,255,.65)}
.q :is(.band,.band-x) .btn.b2:hover{border-color:#fff;background:transparent}
/* שדות: חמישה מצבים */
.q .fld{display:flex;flex-direction:column;gap:8px}
.q .fld label{font-size:13px;font-weight:500;line-height:1.2;color:var(--ink, #16182b)}
.q .in{font:inherit;font-size:16px;line-height:1.2;padding:14px 16px;border:1px solid var(--border-2);border-radius:var(--r-control);background:#fff;color:var(--ink, #16182b);appearance:none;width:100%;transition:border-color .18s var(--ease),box-shadow .18s var(--ease)}
.q .in::placeholder{color:#9ca3af}
.q .in:focus,.q .in.is-focus{outline:0;border-color:var(--accent, #4a3aff);box-shadow:0 0 0 3px color-mix(in srgb,var(--accent, #4a3aff) 22%,transparent)}
.q .fld.err .in{border-color:var(--err)}
