(function(){
  const grid=document.querySelector(".ms"),items=[...grid.querySelectorAll(".ms-item")],GAP=16;
  if(!items.length||!("ResizeObserver" in window))return;   // בלי ResizeObserver נשארת פריסת ה-columns של CSS
  grid.classList.add("ms-on");
  function layout(){
    const W=grid.clientWidth,cols=W<560?1:W<900?2:3,w=(W-GAP*(cols-1))/cols,tops=new Array(cols).fill(0);
    items.forEach(it=>it.style.setProperty("--w",w+"px"));   // קודם כל הרוחבים, ואז קריאת גבהים אחת: בלי layout thrash
    const hs=items.map(it=>it.offsetHeight);                  // הגובה האמיתי: תמונה, טקסט, כל תוכן
    items.forEach((it,i)=>{
      const c=tops.indexOf(Math.min(...tops));
      // RTL: העמודה 0 מימין, לכן מזיזים שמאלה (ערך שלילי)
      it.style.transform="translate("+(-(c*(w+GAP)))+"px,"+tops[c]+"px)";
      it.style.setProperty("--d",(i*70)+"ms");
      tops[c]+=hs[i]+GAP;
    });
    grid.style.height=Math.max(...tops)-GAP+"px";
  }
  layout();
  // גריד וכל פריט: חלון שמשתנה, תמונה שנטענת, טקסט שנשבר אחרת. מתוזמן ל-rAF כדי שהסידור לא ירוץ בתוך קולבק ה-RO
  let raf=0;
  const ro=new ResizeObserver(()=>{cancelAnimationFrame(raf);raf=requestAnimationFrame(layout);});
  ro.observe(grid);items.forEach(it=>ro.observe(it));
  // הכניסה כשהגריד מגיע למסך. בלי threshold באחוזים: גריד ארוך מהמסך לא היה מגיע אליו לעולם
  if("IntersectionObserver" in window){
    new IntersectionObserver((es,o)=>{if(es.some(e=>e.isIntersecting)){grid.classList.add("ready");o.disconnect();}},{rootMargin:"0px 0px -12% 0px"}).observe(grid);
  }else grid.classList.add("ready");
})();

