          .set(txt,{opacity:1})                                           // הטקסט מופיע מאחורי הפס
          .set(bar,{transformOrigin:"0% 50%"})
          .to(bar,{scaleX:0,duration:.5,ease:"power3.inOut"});           // הפס יוצא שמאלה וחושף
      });
    }});
  });
