    gsap.fromTo(".cv-row.r1",{x:0},{x:()=>s*2*D(),ease:"none",scrollTrigger:st});
    gsap.fromTo(".cv-row.r2",{x:()=>s*2*D()},{x:0,ease:"none",scrollTrigger:{...st}});
