/* G149 · שתי תמונות שנפרשות לצדדים וחושפות את הפרויקט */
.pf{overflow-x:clip;padding-block:var(--sec, clamp(120px, 12vw, 260px))}
.pf-head{text-align:center;max-width:52ch;margin:0 auto clamp(20px,6vh,64px);padding-inline:var(--gutter, clamp(24px, 5vw, 96px))}
.pf-head h2{margin:0 0 12px;font-size:var(--fs-h2, clamp(28px, 1.9vw + 0.5rem, 52px))}
