.pf-btn{display:inline-block;border:1px solid var(--ink, #16182b);color:var(--ink, #16182b);padding:12px 24px;text-decoration:none;font-size:15px;transition:background-color .3s,color .3s}
.pf-btn:hover{background:var(--ink, #16182b);color:var(--bg, #f7f7fa)}
/* שתי התמונות יושבות בדיוק באותו מקום, במרכז ומעל הטקסט. JS מזיז אותן */
.pf-img{position:absolute;left:50%;top:50%;z-index:2;width:var(--iw);aspect-ratio:4/5;margin:calc(var(--iw) * -.625) 0 0 calc(var(--iw) * -.5);will-change:transform;
  box-shadow:0 30px 60px -30px color-mix(in srgb,var(--ink, #16182b) 55%,transparent)}
