.hx-sec{display:grid;grid-template-columns:1fr 1.2fr;gap:var(--gap, clamp(16px, 1.6vw, 36px));align-items:center;padding:96px var(--gutter, clamp(24px, 5vw, 96px));border-top:1px solid var(--line, #e4e4ee);scroll-margin-top:88px}
