/* HD3 · הדר גלולה צפה */
/* ---- demo frame (not part of the header): a scrolling mini page ---- */
.hx{position:relative;height:min(80vh,760px);overflow:auto;overscroll-behavior:contain;margin-inline:var(--gutter, clamp(24px, 5vw, 96px));border:1px solid var(--line, #e4e4ee);border-radius:var(--r, 14px);background:var(--bg, #f7f7fa);isolation:isolate;scrollbar-width:thin}
.hx-slot{position:sticky;top:0;height:0;z-index:20}
.hx-hero{min-height:86%;display:flex;flex-direction:column;justify-content:flex-end;gap:16px;padding:112px var(--gutter, clamp(24px, 5vw, 96px)) 64px;
  background:linear-gradient(160deg,color-mix(in srgb,var(--accent, #4a3aff) 34%,var(--ink, #16182b)),var(--ink, #16182b) 72%);color:var(--bg, #f7f7fa)}
.hx-hero.is-light{background:linear-gradient(180deg,color-mix(in srgb,var(--accent, #4a3aff) 9%,var(--bg, #f7f7fa)),var(--bg, #f7f7fa));color:var(--ink, #16182b)}
.hx-hero small{font-size:14px;font-weight:600;opacity:.8}
.hx-hero h3{margin:0;max-width:16ch;font-size:clamp(34px,4.4vw,72px);line-height:1.02;font-weight:700}
.hx-hero p{margin:0;max-width:44ch;font-size:17px;line-height:1.5;opacity:.82}
.hx-sec{display:grid;grid-template-columns:1fr 1.2fr;gap:var(--gap, clamp(16px, 1.6vw, 36px));align-items:center;padding:96px var(--gutter, clamp(24px, 5vw, 96px));border-top:1px solid var(--line, #e4e4ee);scroll-margin-top:88px}
.hx-sec h4{margin:0 0 12px;font-size:clamp(24px,2.2vw,36px);line-height:1.1}
.hx-sec p{margin:0;max-width:40ch;font-size:16px;line-height:1.6;color:var(--muted, #6a6d85)}
.hx-blk{aspect-ratio:4/3;border-radius:var(--r, 14px);background:color-mix(in srgb,var(--ink, #16182b) 7%,var(--bg, #f7f7fa))}
@media (max-width:700px){.hx{height:78vh}.hx-sec{grid-template-columns:1fr;padding:64px var(--gutter, clamp(24px, 5vw, 96px))}.hx-hero{padding:112px var(--gutter, clamp(24px, 5vw, 96px)) 48px}}

/* ---- shared header atoms ---- */
/* the logo link is 44px tall like every other control in the row; the rows centre their items, so nothing moves */
.hlogo{display:inline-flex;align-items:center;justify-content:center;min-height:44px;font-weight:800;font-size:19px;white-space:nowrap;color:inherit;text-decoration:none}
.hlink{display:inline-flex;align-items:center;min-height:44px;padding:0 14px;border-radius:999px;font-size:15px;font-weight:500;color:inherit;text-decoration:none;opacity:.78;
  transition:opacity .15s cubic-bezier(.2,.6,.2,1),background .18s cubic-bezier(.2,.6,.2,1)}
.hbtn{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:0 20px;border-radius:12px;background:var(--accent, #4a3aff);color:var(--accent-ink, #fff);text-decoration:none;
  font-size:14px;font-weight:600;white-space:nowrap;transition:transform .18s cubic-bezier(.2,.6,.2,1),background .3s cubic-bezier(.2,.6,.2,1),color .3s cubic-bezier(.2,.6,.2,1),box-shadow .3s cubic-bezier(.2,.6,.2,1)}
@media (hover:hover) and (pointer:fine){.hlink:hover{opacity:1}.hbtn:hover{transform:translateY(-1px)}}
/* color:inherit: a button does not inherit colour by default, so currentColor lines were browser black on a dark hero (hd1, hd9) */
.hd .burger{display:none;color:inherit}
/* skip link: the first Tab stop on the page, out of sight until it has focus. On a real site it points at <main> */
.hskip{position:absolute;inset-inline-start:16px;top:-64px;z-index:30;display:inline-flex;align-items:center;min-height:44px;padding:0 16px;border-radius:10px;
  background:var(--ink, #16182b);color:var(--bg, #f7f7fa);font-size:15px;font-weight:600;text-decoration:none}
.hskip:focus{top:16px}
/* a hidden header takes its shadow with it: the shadow reaches past the header's own edge (up to 56px on the floating
   ones), and translateY(-100%) left it as a grey band on every light screen while scrolling down (Profix audit, 23.9.2026) */
.hd.is-hidden,.hd.is-hidden::before,.hd.is-hidden > *,.hd.is-hidden > *::before{box-shadow:none!important}
@media (prefers-reduced-motion:reduce){.hd,.hd *{transition-duration:.01ms!important;transition-delay:0s!important}}
/* ---- mobile drawer (shared by b65 and b66) ---- */
.md{position:fixed;inset:0;z-index:60;visibility:hidden;transition:visibility 0s linear .44s}
.md.open{visibility:visible;transition-delay:0s}
.md-scrim{position:absolute;inset:0;background:color-mix(in srgb,var(--ink, #16182b) 48%,transparent);opacity:0;transition:opacity .3s cubic-bezier(.2,.6,.2,1)}
.md.open .md-scrim{opacity:1}
.md-panel{position:absolute;inset-block:0;inset-inline-start:0;width:min(86vw,380px);background:var(--card, #fff);color:var(--ink, #16182b);
  display:flex;flex-direction:column;overflow:auto;padding:18px 24px 32px;box-shadow:0 0 48px color-mix(in srgb,var(--ink, #16182b) 18%,transparent);
  transform:translateX(100%);transition:transform .44s cubic-bezier(.76,0,.24,1)}
[dir="ltr"] .md-panel{transform:translateX(-100%)}
.md.open .md-panel{transform:none}
.md-top{display:flex;align-items:center;justify-content:space-between;padding-bottom:24px}
.md-close{width:44px;height:44px;border:0;border-radius:12px;background:color-mix(in srgb,var(--ink, #16182b) 6%,transparent);color:var(--ink, #16182b);display:grid;place-items:center;cursor:pointer;transition:background .18s cubic-bezier(.2,.6,.2,1),transform .44s cubic-bezier(.76,0,.24,1)}
.md.open .md-close{transform:rotate(90deg)}
.md-close svg{width:18px;height:18px}
.md-list{list-style:none;margin:0;padding:8px 0 0}
.md-item{opacity:0;transform:translateY(12px);
  transition:opacity .18s cubic-bezier(.2,.6,.2,1),transform .18s cubic-bezier(.2,.6,.2,1)}
.md.open .md-item{opacity:1;transform:none;transition-duration:.4s,.4s;transition-delay:calc(.14s + var(--i) * 45ms)}
.md-link,.md-acc{display:flex;align-items:center;justify-content:space-between;width:100%;min-height:56px;padding:12px 0;
  font:inherit;font-size:18px;font-weight:600;color:var(--ink, #16182b);text-decoration:none;background:none;border:0;cursor:pointer;text-align:start;transition:color .15s cubic-bezier(.2,.6,.2,1)}
/* chevron: physical borders on purpose, a logical inline-end flips it sideways in RTL */
.md-acc i{width:8px;height:8px;border-right:2px solid currentColor;border-bottom:2px solid currentColor;transform:rotate(45deg) translateY(-2px);transition:transform .3s cubic-bezier(.2,.6,.2,1)}
.md-acc[aria-expanded="true"]{color:var(--accent, #4a3aff)}
.md-acc[aria-expanded="true"] i{transform:rotate(225deg) translateY(-2px)}
.md-sub{display:grid;grid-template-rows:0fr;transition:grid-template-rows .32s cubic-bezier(.2,.6,.2,1)}
.md-sub.open{grid-template-rows:1fr}
.md-sub>div{overflow:hidden}
.md-sub h5{margin:8px 0 4px;font-size:13px;font-weight:600;color:var(--accent, #4a3aff)}
.md-sub a{display:block;padding:10px 16px;font-size:15px;color:var(--muted, #6a6d85);text-decoration:none;opacity:0;transform:translateX(8px);
  transition:opacity .2s cubic-bezier(.2,.6,.2,1),transform .2s cubic-bezier(.2,.6,.2,1),color .15s cubic-bezier(.2,.6,.2,1)}
[dir="ltr"] .md-sub a{transform:translateX(-8px)}
.md-sub.open a{opacity:1;transform:none;transition-delay:calc(var(--j) * 30ms)}
.md-sub>div>:last-child{margin-bottom:12px}
.md-cta{margin-top:24px;opacity:0;transform:translateY(12px);transition:opacity .18s,transform .18s}
.md.open .md-cta{opacity:1;transform:none;transition:opacity .4s cubic-bezier(.2,.6,.2,1) .42s,transform .4s cubic-bezier(.2,.6,.2,1) .42s}
.md-cta a{display:flex;justify-content:center;align-items:center;min-height:52px;border-radius:12px;background:var(--accent, #4a3aff);color:var(--accent-ink, #fff);font-weight:600;text-decoration:none}
@media (hover:hover) and (pointer:fine){.md-link:hover,.md-acc:hover,.md-sub a:hover{color:var(--accent, #4a3aff)}.md-close:hover,.burger:hover{background:color-mix(in srgb,var(--ink, #16182b) 12%,transparent)}}
.burger{width:44px;height:44px;border:0;transition:background .18s cubic-bezier(.2,.6,.2,1);border-radius:12px;background:color-mix(in srgb,var(--ink, #16182b) 6%,transparent);display:grid;place-content:center;gap:4px;cursor:pointer}
.burger i{display:block;width:18px;height:2px;background:var(--ink, #16182b);border-radius:2px;transition:transform .36s cubic-bezier(.76,0,.24,1),opacity .2s}
.burger[aria-expanded="true"] i:nth-child(1){transform:translateY(6px) rotate(45deg)}
.burger[aria-expanded="true"] i:nth-child(2){opacity:0}
.burger[aria-expanded="true"] i:nth-child(3){transform:translateY(-6px) rotate(-45deg)}
@media (prefers-reduced-motion:reduce){.md,.md *{transition-duration:.01ms!important;transition-delay:0s!important}}
.h3x{position:absolute;top:16px;inset-inline:0;margin-inline:auto;width:min(880px,calc(100% - 32px));display:flex;align-items:center;gap:16px;padding:8px;padding-inline-start:24px;
  border-radius:999px;isolation:isolate;color:var(--ink, #16182b);--hy:0px;--hs:1;transform:translateY(var(--hy)) scale(var(--hs));transition:transform .45s cubic-bezier(.2,.6,.2,1)}
.h3x::before{content:"";position:absolute;inset:0;z-index:-1;border-radius:inherit;background:color-mix(in srgb,var(--card, #fff) 78%,transparent);
  backdrop-filter:blur(14px) saturate(1.4);-webkit-backdrop-filter:blur(14px) saturate(1.4);border:1px solid color-mix(in srgb,var(--ink, #16182b) 10%,transparent);
  box-shadow:0 8px 24px color-mix(in srgb,var(--ink, #16182b) 8%,transparent);transition:box-shadow .3s cubic-bezier(.2,.6,.2,1),background .3s cubic-bezier(.2,.6,.2,1)}
.h3x.is-scrolled{--hs:.97}
.h3x.is-scrolled::before{background:color-mix(in srgb,var(--card, #fff) 92%,transparent);box-shadow:0 16px 40px color-mix(in srgb,var(--ink, #16182b) 14%,transparent)}
.h3x.is-hidden{--hy:calc(-100% - 32px)}
.h3x nav{display:flex;gap:2px;margin-inline:auto}
.h3x .hbtn{border-radius:999px}
.h3x .burger{border-radius:999px}
@media (hover:hover) and (pointer:fine){.h3x .hlink:hover{background:color-mix(in srgb,var(--ink, #16182b) 6%,transparent)}}
@media (max-width:900px){.h3x{padding-inline-start:20px}.h3x nav,.h3x .hbtn{display:none}.h3x .burger{display:grid;margin-inline-start:auto}}

