@media (prefers-reduced-motion:reduce){.md,.md *{transition-duration:.01ms!important;transition-delay:0s!important}}
.h9x{position:absolute;top:16px;inset-inline:0;margin-inline:auto;width:min(880px,calc(100% - 32px));display:flex;align-items:center;gap:16px;padding:8px;padding-inline-start:24px;
  border-radius:999px;isolation:isolate;color:var(--bg, #f7f7fa);--hy:0px;--hs:1;transform:translateY(var(--hy)) scale(var(--hs));
