  rows.forEach(function(r){
    var i=+r.dataset.img;
    if(fine)r.addEventListener("mouseenter",function(){show(i,r);});
    // keyboard and touch get the same result without hover: focus, and tap
    r.addEventListener("focus",function(){show(i,r);});
