/* H17 · הירו צילום מלא עם שורת הזמנה */
/* ---- demo frame and top row (scaffolding, not part of the hero) ---- */
.hf{position:relative;margin-inline:var(--gutter, clamp(24px, 5vw, 96px));border:1px solid var(--line, #e4e4ee);border-radius:var(--r, 14px);overflow:hidden;background:var(--bg, #f7f7fa);isolation:isolate}
.hf-top{position:absolute;inset-inline:0;top:0;z-index:6;display:flex;align-items:center;gap:24px;padding:20px 28px;font-size:15px;font-weight:500}
.hf-top b{font-size:18px;font-weight:800}
.hf-top nav{display:flex;gap:18px;margin-inline-start:auto;opacity:.8}
@media (max-width:760px){.hf-top nav{display:none}}
.hbtn{display:inline-flex;align-items:center;justify-content:center;min-height:52px;padding:0 28px;border-radius:12px;background:var(--accent, #4a3aff);color:var(--accent-ink, #fff);text-decoration:none;
  font-size:16px;font-weight:600;white-space:nowrap;transition:transform .18s cubic-bezier(.2,.6,.2,1),box-shadow .3s cubic-bezier(.2,.6,.2,1)}
.hbtn.ghost{background:none;color:inherit;box-shadow:inset 0 0 0 1.5px currentColor}
@media (hover:hover) and (pointer:fine){.hbtn:hover{transform:translateY(-2px)}}
.hkick{font-size:14px;font-weight:600;letter-spacing:.02em;opacity:.75}
.hlead{margin:0;font-size:clamp(17px,1.2vw,20px);line-height:1.55;opacity:.82}
.hmicro{display:flex;flex-wrap:wrap;gap:8px 18px;font-size:14px;opacity:.7}
.hcta{display:flex;flex-wrap:wrap;gap:12px}

/* the resting state is the visible one. opacity:1 on .rv also keeps the no-JS look identical to the look after the entrance */
.rv{opacity:1;transition:opacity .5s cubic-bezier(.2,.6,.2,1),transform .5s cubic-bezier(.2,.6,.2,1)}
.open-anim .rv{opacity:0;transform:translateY(18px);animation:rv-fs 0s 2.5s forwards}
/* --t0: on a page with a header, 0.2s so the header comes down first (motion.md 2) */
.is-in .rv{opacity:1;transform:none;transition-duration:.7s;transition-delay:calc(var(--t0,0s) + var(--i,0) * 90ms)}
.rv-on .rv{animation:none}
@keyframes rv-fs{to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.rv,.is-in .rv{transition-duration:.01ms!important;transition-delay:0s!important}
  .hbtn{transition-duration:.01ms!important}.hbtn:hover{transform:none!important}}
.h17h{position:relative;display:flex;flex-direction:column;justify-content:flex-end;gap:32px;min-height:min(86vh,780px);padding:112px 28px 28px;background:var(--ink, #16182b);color:var(--bg, #f7f7fa);overflow:hidden;isolation:isolate}
.h17-bg{position:absolute;inset:0;z-index:-2}
.h17-bg img{width:100%;height:100%;object-fit:cover;object-position:62% 50%;display:block;transition:transform 1.1s cubic-bezier(.2,.6,.2,1)}
.open-anim .h17-bg img{transform:scale(1.06);animation:rv-fs 0s 2.5s forwards}
.is-in .h17-bg img{transform:none;transition-delay:var(--t0,0s)}
.rv-on .h17-bg img{animation:none}
/* diagonal scrim from the corner of the text (heroes.md); the bar carries its own surface, so it needs none */
.h17-scrim{position:absolute;inset:0;z-index:-1;background:linear-gradient(to top left,color-mix(in srgb,var(--ink, #16182b) 80%,transparent) 0%,color-mix(in srgb,var(--ink, #16182b) 38%,transparent) 48%,transparent 78%)}
[dir="ltr"] .h17-scrim{background:linear-gradient(to top right,color-mix(in srgb,var(--ink, #16182b) 80%,transparent) 0%,color-mix(in srgb,var(--ink, #16182b) 38%,transparent) 48%,transparent 78%)}
.h17-txt{display:flex;flex-direction:column;align-items:flex-start;gap:20px;max-width:640px}
.h17h h3{margin:0;font-size:clamp(36px,min(4.6vw,7.8vh),76px);line-height:1.03;font-weight:700;letter-spacing:-.01em;text-wrap:balance}
.h17h .hlead{max-width:44ch;opacity:.9}
.h17-book{display:flex;flex-direction:column;gap:12px;max-width:940px}
.h17-bar{display:grid;grid-template-columns:repeat(3,minmax(0,1fr)) auto;gap:8px;padding:8px;border-radius:18px;background:var(--bg, #f7f7fa);color:var(--ink, #16182b);
  box-shadow:0 24px 60px -24px color-mix(in srgb,var(--ink, #16182b) 70%,transparent)}
.h17-f{display:flex;flex-direction:column;justify-content:center;gap:2px;min-width:0;padding:8px 16px;border-radius:12px;cursor:pointer;transition:background .2s cubic-bezier(.2,.6,.2,1)}
.h17-f span{font-size:12px;font-weight:600;color:var(--muted, #6a6d85)}
.h17-f input,.h17-f select{width:auto;max-width:100%;min-width:0;height:24px;border:0;padding:0;background:none;color:var(--ink, #16182b);font:inherit;font-size:16px;font-weight:600;outline:none;cursor:pointer}
@media (hover:hover) and (pointer:fine){.h17-f:hover{background:color-mix(in srgb,var(--ink, #16182b) 4%,transparent)}}
.h17-f:focus-within{background:color-mix(in srgb,var(--ink, #16182b) 7%,transparent)}
.h17-bar .hbtn{border:0;font:inherit;font-size:16px;font-weight:600;cursor:pointer}
.h17-bar .hbtn:focus-visible{outline:2px solid var(--ink, #16182b);outline-offset:3px}
.h17-res{margin:0;min-height:1.5em;font-size:15px;font-weight:600}
@media (prefers-reduced-motion:reduce){.h17-bg img{transition-duration:.01ms!important;transition-delay:0s!important}}
/* phone: the date takes a full row, nights and guests share one, the button closes */
@media (max-width:860px){.h17h{padding:96px 20px 20px;gap:24px;min-height:min(92vh,800px)}
  .h17h h3{font-size:clamp(30px,8vw,40px)}
  .h17-bar{grid-template-columns:1fr 1fr}
  .h17-f{padding:8px 12px}
  .h17-f:first-child,.h17-bar .hbtn{grid-column:1 / -1}}

