    requestAnimationFrame(function f(now){
      if(touched)return; if(!t0)t0=now;
      var k=Math.min((now-t0)/1200,1);
      set(k<1?(50+16*Math.sin(k*Math.PI*2)*(1-k/2)).toFixed(2):50);
      if(k<1)requestAnimationFrame(f);
    });
