    var t0=null, done=false;
    function fin(){done=true;num.textContent=String(to);}
    function step(t){
      if(done)return;
      if(t0===null)t0=t;
      var p=Math.min((t-t0)/1000,1);
      num.textContent=String(Math.round(from+(to-from)*(1-Math.pow(1-p,3))));
