      var gu=guess.querySelector("[data-gu]");gu.textContent="";
      marked(p,best.u).forEach(function(c){var n=c[1]?document.createElement("mark"):document.createTextNode(c[0]);if(c[1])n.textContent=c[0];gu.appendChild(n);});
