.cx-demo{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:0 0 24px;padding:6px;border-radius:14px;background:color-mix(in srgb,var(--ink, #16182b) 5%,transparent);font-size:13px;width:max-content;max-width:100%}
.cx-demo > span{padding:0 10px;font-weight:600;color:var(--muted, #6a6d85)}
.cx-demo button{min-height:36px;padding:0 14px;border:0;border-radius:10px;background:none;font:inherit;font-weight:600;color:var(--ink, #16182b);cursor:pointer;transition:background .18s cubic-bezier(.2,.6,.2,1),color .18s cubic-bezier(.2,.6,.2,1)}
.cx-demo button[aria-pressed="true"]{background:var(--card, #fff);box-shadow:0 1px 3px color-mix(in srgb,var(--ink, #16182b) 14%,transparent)}
.cx-demo input{min-height:36px;padding:0 12px;border:0;border-radius:10px;background:var(--card, #fff);font:inherit;font-size:14px;color:var(--ink, #16182b);width:220px}
@media (prefers-reduced-motion:reduce){.cx *,.cx *::before,.cx *::after{transition-duration:.01ms!important;transition-delay:0s!important;animation-duration:.01ms!important;animation-iteration-count:1!important}.cx-rv{opacity:1;transform:none}}
.cxw{margin-inline:var(--gutter, clamp(24px, 5vw, 96px));border-radius:var(--r, 14px);background:var(--bg, #f7f7fa);box-shadow:0 0 0 1px var(--line, #e4e4ee);overflow:hidden;isolation:isolate}
.cxw-in{max-width:640px;margin-inline:auto;padding:72px 24px 88px}
@media (max-width:700px){.cxw-in{padding:48px 20px 64px}}
.t7-h{margin:0 0 8px;font-size:clamp(28px,3.8vw,40px);line-height:1.12;font-weight:700}
.t7-sub{margin:0 0 24px;color:var(--muted, #6a6d85)}
.t7-trail{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:0 0 48px;padding:0;list-style:none}
.t7-trail li{display:flex;align-items:center;gap:6px}
/* the separators are decoration: an empty alt text keeps screen readers from saying "angle bracket";
   the plain value comes first, for browsers that do not know the alt syntax */
.t7-trail li + li::before{content:"‹";content:"‹" / "";color:var(--muted, #6a6d85);font-size:18px}
[dir="ltr"] .t7-trail li + li::before{content:"›";content:"›" / ""}
.t7-c{position:relative;display:inline-flex;align-items:center;min-height:40px;padding:0 14px;border-radius:999px;background:var(--card, #fff);font-size:15px;font-weight:600;text-decoration:none;
  transition:background .18s cubic-bezier(.2,.6,.2,1),color .18s cubic-bezier(.2,.6,.2,1)}
a.t7-c{box-shadow:inset 0 0 0 1.5px color-mix(in srgb,var(--ink, #16182b) 10%,transparent)}
@media (hover:hover) and (pointer:fine){a.t7-c:hover{background:var(--ink, #16182b);color:var(--bg, #f7f7fa)}}
.t7-bad{color:var(--cx-err);background:color-mix(in srgb,var(--cx-err) 8%,transparent);unicode-bidi:isolate}
/* the strike is drawn in the reading direction of the address (left to right), after the trail has settled */
.t7-bad::after{content:"";position:absolute;left:12px;right:12px;top:50%;height:2px;border-radius:2px;background:currentColor;transform:scaleX(0);transform-origin:left;transition:transform .45s cubic-bezier(.2,.6,.2,1) .5s}
.is-in .t7-bad::after{transform:scaleX(1)}
.t7-fix::before{content:"←";content:"←" / "";margin-inline-end:6px;opacity:.8}
[dir="ltr"] .t7-fix::before{content:"→";content:"→" / ""}
.t7-fix{background:var(--accent, #4a3aff);color:var(--accent-ink, #fff);opacity:0;transform:translateX(8px);transition:opacity .3s cubic-bezier(.2,.6,.2,1) .95s,transform .3s cubic-bezier(.2,.6,.2,1) .95s,background .18s cubic-bezier(.2,.6,.2,1)}
.is-in .t7-fix{opacity:1;transform:none}
.t7-skip{color:var(--muted, #6a6d85);background:transparent;box-shadow:inset 0 0 0 1.5px color-mix(in srgb,var(--ink, #16182b) 10%,transparent);unicode-bidi:isolate}
.t7-top h3{margin:0 0 16px;font-size:15px;font-weight:600;color:var(--muted, #6a6d85)}
.t7-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:0 0 40px}
.t7-grid a{display:grid;grid-template-columns:minmax(0,1fr);gap:12px;padding:12px 12px 16px;border-radius:18px;background:var(--card, #fff);text-decoration:none;transition:transform .2s cubic-bezier(.2,.6,.2,1),box-shadow .2s cubic-bezier(.2,.6,.2,1)}
.t7-grid i{display:block;min-width:0;aspect-ratio:2/1;border-radius:12px;background:color-mix(in srgb,var(--accent, #4a3aff) calc(var(--k) * 8%),var(--bg, #f7f7fa));transition:transform .4s cubic-bezier(.2,.6,.2,1)}
.t7-grid b{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:0 4px;font-size:16px}
.t7-grid b svg{width:16px;height:16px}
@media (hover:hover) and (pointer:fine){.t7-grid a:hover{transform:translateY(-2px);box-shadow:0 14px 32px color-mix(in srgb,var(--ink, #16182b) 10%,transparent)}}
.t7-rep{display:flex;flex-wrap:wrap;align-items:center;gap:12px 16px;padding:20px;border-radius:18px;background:color-mix(in srgb,var(--ink, #16182b) 4%,transparent)}
.t7-rep[hidden]{display:none}
.t7-rep p{flex:1 1 240px;margin:0;font-size:15px;color:var(--muted, #6a6d85)}
.t7-rep .cx-btn{min-height:48px;font-size:15px;overflow:hidden}
.t7-rep .cx-btn span{display:inline-flex;align-items:center;gap:8px;transition:transform .25s cubic-bezier(.2,.6,.2,1),opacity .25s cubic-bezier(.2,.6,.2,1)}
.t7-rep .cx-btn span + span{position:absolute;inset:0;justify-content:center;opacity:0;transform:translateY(100%)}
.t7-rep .cx-btn span svg{width:16px;height:16px}
.t7-rep .is-sent span:first-child{opacity:0;transform:translateY(-100%)}
.t7-rep .is-sent span + span{opacity:1;transform:none}
.t7-rep .is-sent{background:var(--ink, #16182b);color:var(--bg, #f7f7fa);pointer-events:none}
/* read by screen readers only: the live report line, and "not found:" before the broken part of the trail.
   Its own rule, so the component does not depend on a page-level .sr-only */
.t7-said{position:absolute;width:1px;height:1px;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
@media (pointer:coarse),(max-width:760px){.t7-c{min-height:44px}}

