function inView(el,f){
  var done=false,io=null;
  function go(){if(done)return;done=true;off();f();}
  function chk(){var r=el.getBoundingClientRect();if(r.top<innerHeight*.9&&r.bottom>0)go();}
  function off(){removeEventListener("scroll",chk);removeEventListener("resize",chk);if(io)io.disconnect();}
  // the observer also catches a layout change that brings the block on screen with no scroll event;
  // the scroll check stays for where the observer is late or missing
  if("IntersectionObserver" in window){io=new IntersectionObserver(function(es){if(es.some(function(x){return x.isIntersecting;}))go();},{rootMargin:"0px 0px -10% 0px"});io.observe(el);}
  addEventListener("scroll",chk,{passive:true});addEventListener("resize",chk);requestAnimationFrame(chk);setTimeout(chk,300);
}
function lev(a,b){var m=a.length,n=b.length,d=[],i,j;for(i=0;i<=m;i++)d[i]=[i];for(j=0;j<=n;j++)d[0][j]=j;
  for(i=1;i<=m;i++)for(j=1;j<=n;j++)d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+(a[i-1]===b[j-1]?0:1));return d;}
(function(){
  var root=document.getElementById("cv7");
  // the routes that exist, by path, with their Hebrew name
  var MAP={"services":"שירותים","services/kitchen-design":"עיצוב מטבחים","services/living-room":"עיצוב סלון","services/renovation":"שיפוץ מלא","projects":"פרויקטים","pricing":"מחירים","contact":"צור קשר"};
  var raw=root.getAttribute("data-demo-path")||location.pathname,segs=raw.split("/").filter(Boolean),trail=root.querySelector("[data-trail]"),acc="",broken=false;
  function chip(tag,cls,text,href){var li=document.createElement("li"),c=document.createElement(tag);c.className="t7-c "+cls;c.textContent=text;if(href)c.href=href;if(cls!=="")c.dir=cls.indexOf("t7-bad")>-1||cls.indexOf("t7-skip")>-1?"ltr":"";li.appendChild(c);trail.appendChild(li);return c;}
  chip("a","","בית","/");
  segs.forEach(function(s){
    var next=(acc?acc+"/":"")+s.toLowerCase();
    if(broken){chip("span","t7-skip",s);return;}
    if(MAP[next]){chip("a","",MAP[next],"/"+next);acc=next;return;}
    broken=true;var bad=chip("span","t7-bad",s);
    // an aria-label on a plain span is not read: the "not found" goes in as hidden text before the part
    var said=document.createElement("span");said.className="t7-said";said.textContent="לא קיים: ";bad.prepend(said);
    // the nearest sibling under the last part that worked
    var best=null,bs=1;Object.keys(MAP).forEach(function(k){if(k.indexOf(acc?acc+"/":"")!==0||k.split("/").length!==next.split("/").length)return;
      var t=k.split("/").pop(),d=lev(s.toLowerCase(),t),r=d[s.length][t.length]/Math.max(s.length,t.length);if(r<bs){bs=r;best=k;}});
    // the suggestion sits in the same step as the broken part, not after a separator: it replaces it, it does not continue the path
    if(best&&bs<=.4){var f=document.createElement("a");f.className="t7-c t7-fix";f.href="/"+best;f.textContent=MAP[best];bad.parentNode.appendChild(f);}
  });
  // the report: path and where the visitor came from. sendBeacon survives the visitor leaving the page right after.
  var btn=root.querySelector("[data-report]"),said=root.querySelector("[data-said]"),url=root.getAttribute("data-report-url");
  // no endpoint wired and not the vault demo: no button at all, never a "thanks" for a report that went nowhere
  if(!url&&!root.hasAttribute("data-demo"))root.querySelector(".t7-rep").hidden=true;
  btn.addEventListener("click",function(){
    var body=JSON.stringify({path:raw,from:document.referrer||"direct",at:new Date().toISOString()});
    if(url&&navigator.sendBeacon)navigator.sendBeacon(url,body);
    btn.classList.add("is-sent");btn.setAttribute("aria-disabled","true");said.textContent="הדיווח נשלח. תודה, נתקן.";
  });
  inView(root,function(){root.classList.add("is-in");});
})();

entries.css:
/* CV8 · שליחה שלא מאבדת אף ליד */
.cx *{box-sizing:border-box}
.cx{--cx-err:color-mix(in srgb,#d23b22 72%,var(--ink, #16182b));font-size:16px;line-height:1.6;color:var(--ink, #16182b)}
.cx :where(a){color:inherit}
.cx :where(h2,h3){text-wrap:balance}
.cx :where(p,small,li){text-wrap:pretty}
.cx :focus-visible{outline:2px solid var(--accent, #4a3aff);outline-offset:3px;border-radius:8px}
.cx-btn{position:relative;display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:52px;padding:0 24px;border:0;border-radius:14px;
  background:var(--accent, #4a3aff);color:var(--accent-ink, #fff);font:inherit;font-size:16px;font-weight:600;text-decoration:none;cursor:pointer;white-space:nowrap;
  transition:transform .18s cubic-bezier(.2,.6,.2,1),background .2s cubic-bezier(.2,.6,.2,1),box-shadow .2s cubic-bezier(.2,.6,.2,1)}
.cx-btn svg{width:20px;height:20px;flex:none}
.cx-btn:active{transform:scale(.97)}
.cx-btn.is-ghost{background:transparent;color:var(--ink, #16182b);box-shadow:inset 0 0 0 1.5px color-mix(in srgb,var(--ink, #16182b) 22%,transparent)}
@media (hover:hover) and (pointer:fine){.cx-btn:hover{transform:translateY(-1px)}.cx-btn.is-ghost:hover{box-shadow:inset 0 0 0 1.5px var(--ink, #16182b)}
  .cx a:hover .ic-arr,.cx-btn:hover .ic-arr{transform:translateX(-4px)}}
.ic-arr{transition:transform .2s cubic-bezier(.2,.6,.2,1)}
[dir="ltr"] .ic-arr{rotate:180deg}
.cx-rv{opacity:0;transform:translateY(16px);transition:opacity .5s cubic-bezier(.2,.6,.2,1),transform .5s cubic-bezier(.2,.6,.2,1);transition-delay:calc(var(--i,0) * 80ms)}
.is-in .cx-rv{opacity:1;transform:none}
/* a time or a phone number never breaks between rows ("050-000" on one, "0000" on the next, at 500) */
.cx-t{unicode-bidi:isolate;font-variant-numeric:tabular-nums;white-space:nowrap}
/* the demo switch: lets the reviewer see every state. Not part of the component you copy. */
.cx-demo{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:0 0 24px;padding:6px;border-radius:14px;background:color-mix(in srgb,var(--ink, #16182b) 5%,transparent);font-size:13px;width:max-content;max-width:100%}
.cx-demo > span{padding:0 10px;font-weight:600;color:var(--muted, #6a6d85)}
.cx-demo button{min-height:36px;padding:0 14px;border:0;border-radius:10px;background:none;font:inherit;font-weight:600;color:var(--ink, #16182b);cursor:pointer;transition:background .18s cubic-bezier(.2,.6,.2,1),color .18s cubic-bezier(.2,.6,.2,1)}
.cx-demo button[aria-pressed="true"]{background:var(--card, #fff);box-shadow:0 1px 3px color-mix(in srgb,var(--ink, #16182b) 14%,transparent)}
.cx-demo input{min-height:36px;padding:0 12px;border:0;border-radius:10px;background:var(--card, #fff);font:inherit;font-size:14px;color:var(--ink, #16182b);width:220px}
@media (prefers-reduced-motion:reduce){.cx *,.cx *::before,.cx *::after{transition-duration:.01ms!important;transition-delay:0s!important;animation-duration:.01ms!important;animation-iteration-count:1!important}.cx-rv{opacity:1;transform:none}}
.cxw{margin-inline:var(--gutter, clamp(24px, 5vw, 96px));border-radius:var(--r, 14px);background:var(--bg, #f7f7fa);box-shadow:0 0 0 1px var(--line, #e4e4ee);overflow:hidden;isolation:isolate}
.cxw-in{max-width:640px;margin-inline:auto;padding:72px 24px 88px}
@media (max-width:700px){.cxw-in{padding:48px 20px 64px}}
.f8-h{margin:0 0 8px;font-size:clamp(26px,3.4vw,36px);line-height:1.15;font-weight:700}
.f8-sub{margin:0 0 28px;color:var(--muted, #6a6d85)}
.f8 form{display:grid;gap:16px}
.f8 label{display:grid;gap:8px;font-size:14px;font-weight:600}
.f8 input,.f8 textarea{width:100%;min-height:52px;padding:14px 16px;border:0;border-radius:14px;background:var(--card, #fff);font:inherit;font-weight:400;color:var(--ink, #16182b);resize:vertical;
  box-shadow:inset 0 0 0 1.5px color-mix(in srgb,var(--ink, #16182b) 12%,transparent);transition:box-shadow .18s cubic-bezier(.2,.6,.2,1)}
.f8 textarea{min-height:96px}
.f8 input:focus,.f8 textarea:focus{outline:0;box-shadow:inset 0 0 0 2px var(--accent, #4a3aff)}
.f8-btn{justify-self:start;min-width:180px;overflow:hidden}
.f8-btn [data-lab]{display:inline-block}
.f8-btn [data-lab].in{animation:f8-lab .22s cubic-bezier(.2,.6,.2,1)}
@keyframes f8-lab{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
.f8-spin{display:none;width:18px;height:18px;border-radius:50%;box-shadow:inset 0 0 0 2px color-mix(in srgb,var(--accent-ink, #fff) 30%,transparent);border-top:2px solid var(--accent-ink, #fff);animation:f8-spin .8s linear infinite}
@keyframes f8-spin{to{transform:rotate(360deg)}}
[data-state="sending"] .f8-spin{display:block}
[data-state="sending"] .f8-btn{cursor:progress}
.f8-ok{display:none;width:20px;height:20px}
.f8-ok path{stroke-dasharray:24;stroke-dashoffset:24;animation:f8-draw .35s cubic-bezier(.2,.6,.2,1) .05s forwards}
@keyframes f8-draw{to{stroke-dashoffset:0}}
[data-state="sent"] .f8-ok{display:block}
[data-state="sent"] .f8-btn{background:var(--ink, #16182b);color:var(--bg, #f7f7fa);pointer-events:none}
/* the panel opens by its row track, so nothing below it jumps */
.f8-panel{display:grid;grid-template-rows:0fr;transition:grid-template-rows .35s cubic-bezier(.2,.6,.2,1)}
.f8-panel.is-open{grid-template-rows:1fr}
.f8-panel > div{overflow:hidden;min-height:0}
.f8-box{display:grid;grid-template-columns:auto 1fr;gap:4px 14px;margin-top:8px;padding:18px 20px;border-radius:16px;background:color-mix(in srgb,var(--cx-err) 7%,var(--bg, #f7f7fa))}
[data-kind="offline"] .f8-box{background:color-mix(in srgb,var(--ink, #16182b) 6%,var(--bg, #f7f7fa))}
[data-kind="ok"] .f8-box{background:color-mix(in srgb,var(--accent, #4a3aff) 9%,var(--bg, #f7f7fa))}
.f8-ic{grid-row:span 2;width:24px;height:24px;color:var(--cx-err)}
[data-kind="offline"] .f8-ic{color:var(--muted, #6a6d85)}
[data-kind="ok"] .f8-ic{color:var(--accent, #4a3aff)}
.f8-ic svg{display:block;width:24px;height:24px}
.f8-ic > span{display:none}
[data-kind="error"] .f8-ic .i-err,[data-kind="offline"] .f8-ic .i-off,[data-kind="ok"] .f8-ic .i-ok{display:block}
.f8-box b{font-size:16px;line-height:1.4}
.f8-box p{margin:0;display:flex;align-items:center;gap:10px;font-size:15px;color:var(--muted, #6a6d85)}
.f8-ring{width:20px;height:20px;flex:none;transform:rotate(-90deg)}
.f8-ring circle{fill:none;stroke:var(--cx-err);stroke-width:1.8;stroke-dasharray:50.3;stroke-dashoffset:0}
.f8-ring.run circle{animation:f8-count var(--t,5s) linear forwards}
@keyframes f8-count{to{stroke-dashoffset:50.3}}
[data-kind="offline"] .f8-ring,[data-kind="ok"] .f8-ring,.is-final .f8-ring{display:none}
.f8-acts{grid-column:2;display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}
.f8-acts .cx-btn{min-height:44px;padding:0 16px;font-size:14px}
[data-kind="ok"] .f8-acts{display:none}
/* a missing field is not a failed send: no ring, no fallback buttons, just what is missing */
[data-kind="field"] .f8-acts,[data-kind="field"] .f8-ring{display:none}
[data-kind="field"] .f8-ic .i-err{display:block}
.f8 input[aria-invalid="true"]{box-shadow:inset 0 0 0 2px color-mix(in srgb,var(--cx-err) 70%,transparent)}
.f8 input[aria-invalid="true"]:focus{box-shadow:inset 0 0 0 2px var(--cx-err)}
/* after the third failure a phone number in a sentence cannot be tapped: it becomes a button */
.f8-tel{display:none}
.is-final .f8-tel{display:inline-flex}
/* waiting for the network is not an action the visitor can take: the button says so and steps back */
[data-state="offline"] .f8-btn{background:color-mix(in srgb,var(--ink, #16182b) 8%,var(--bg, #f7f7fa));color:var(--ink, #16182b);cursor:default}
/* offline: a slow breathing dot says "waiting", not "broken" */
.f8-wait{display:none;width:8px;height:8px;border-radius:50%;background:var(--muted, #6a6d85);animation:f8-breathe 1.6s cubic-bezier(.2,.6,.2,1) infinite}
[data-kind="offline"] .f8-wait{display:block}
@keyframes f8-breathe{50%{opacity:.25}}

