(function(){
  var root=document.getElementById("cv8"),form=root.querySelector("form"),btn=form.querySelector(".f8-btn"),lab=btn.querySelector("[data-lab]"),panel=root.querySelector("[data-panel]");
  var msg=panel.querySelector("[data-msg]"),sub=panel.querySelector("[data-sub]"),ring=panel.querySelector(".f8-ring"),wa=panel.querySelector("[data-wa]");
  var KEY="cv8-draft",mode="fail",tries=0,timer=0,busy=false,waiting=false,NL=String.fromCharCode(10);
  // demo only: how the server behaves. On a real site send() is your fetch, and there is no switch.
  root.querySelectorAll("[data-mode]").forEach(function(b){b.addEventListener("click",function(){
    mode=b.getAttribute("data-mode");root.querySelectorAll("[data-mode]").forEach(function(x){x.setAttribute("aria-pressed",String(x===b));});
    if(root.getAttribute("data-state")==="sent"){state("idle");setLab("שליחה");panel.classList.remove("is-open");}
    if(mode!=="offline"&&waiting)dispatchEvent(new Event("online"));
  });});
  function online(){return mode==="offline"?false:navigator.onLine;}
  function send(o){return new Promise(function(res,rej){setTimeout(function(){if(mode==="ok")res();else rej(new Error("500"));},1100);});}
  // the draft: every keystroke is kept, so a failure, a refresh or a dead battery do not cost the lead
  // what is kept is not what is sent: a field with data-nokeep, a password, a hidden field or card details never reach the draft
  var fields=[].slice.call(form.elements).filter(function(f){return f.name;});
  var kept=fields.filter(function(f){return !f.matches("[type=password],[type=hidden],[data-nokeep],[autocomplete^=cc-]");});
  try{var d=JSON.parse(localStorage.getItem(KEY)||"{}");kept.forEach(function(f){if(d[f.name])f.value=d[f.name];});}catch(e){}
  var st=0;form.addEventListener("input",function(ev){
    if(ev.target.hasAttribute("aria-invalid")){ev.target.removeAttribute("aria-invalid");if(panel.getAttribute("data-kind")==="field")panel.classList.remove("is-open");}
    clearTimeout(st);st=setTimeout(function(){var o={};kept.forEach(function(f){o[f.name]=f.value;});try{localStorage.setItem(KEY,JSON.stringify(o));}catch(e){}},300);});
  function data(){var o={};fields.forEach(function(f){o[f.name]=f.value.trim();});return o;}
  function state(s){root.setAttribute("data-state",s);}
  function setLab(t){lab.classList.remove("in");void lab.offsetWidth;lab.textContent=t;lab.classList.add("in");}
  function show(kind,m,s){panel.setAttribute("data-kind",kind);msg.textContent=m;sub.removeAttribute("aria-hidden");sub.textContent=s||"";panel.classList.add("is-open");}
  function inSec(n){return n===1?"בעוד שנייה":"בעוד "+n+" שניות";}
  // the count is seen, not read aloud: inside the live panel it would be announced every second
  function countdown(sec){
    clearInterval(timer);var left=sec;ring.style.setProperty("--t",sec+"s");ring.classList.remove("run");void ring.getBoundingClientRect();ring.classList.add("run");
    sub.setAttribute("aria-hidden","true");sub.textContent="ננסה שוב לבד "+inSec(left);
    timer=setInterval(function(){left--;if(left<=0){clearInterval(timer);submit();}else sub.textContent="ננסה שוב לבד "+inSec(left);},1000);
  }
  function submit(){
    if(busy)return;
    // a missing field stops any retry, says what is missing and marks the field, instead of a silent jump of the focus
    var o=data();if(!o.name||!o.phone){clearInterval(timer);var el=form.querySelector(o.name?"[name=phone]":"[name=name]");
      show("field",o.name?"חסר מספר טלפון.":"חסר שם.","");el.setAttribute("aria-invalid","true");el.focus();return;}
    busy=true;clearInterval(timer);btn.style.minWidth=btn.offsetWidth+"px";
    // WhatsApp carries the same details, so the fallback costs the visitor one tap and no retyping
    wa.href="https://wa.me/972500000000?text="+encodeURIComponent("היי, ניסיתי לשלוח פנייה באתר ולא עבר."+NL+"שם: "+o.name+NL+"טלפון: "+o.phone+(o.msg?NL+o.msg:""));
    if(!online()){busy=false;waiting=true;state("offline");setLab("ממתין לחיבור");show("offline","אין חיבור לאינטרנט. הפרטים שמורים.","הטופס יישלח לבד ברגע שהחיבור יחזור.");return;}
    state("sending");setLab("שולח");panel.classList.remove("is-open");btn.setAttribute("aria-busy","true");
    send(o).then(function(){
      busy=false;tries=0;btn.removeAttribute("aria-busy");state("sent");setLab("נשלח");try{localStorage.removeItem(KEY);}catch(e){}
      show("ok","קיבלנו. נחזור אליכם עוד היום.","");
    },function(){
      busy=false;tries++;btn.removeAttribute("aria-busy");state("error");setLab("לשלוח עכשיו");
      if(tries<3){panel.classList.remove("is-final");show("error","לא הצלחנו לשלוח. הפרטים שמורים אצלכם.","");countdown(tries===1?5:10);}
      else{panel.classList.add("is-final");show("error","השרת לא עונה כרגע. הפרטים שמורים.","הכי מהיר עכשיו: וואטסאפ או שיחה.");}
    });
  }
  form.addEventListener("submit",function(e){e.preventDefault();tries=0;submit();});
  addEventListener("online",function(){if(waiting&&online()){waiting=false;submit();}});
})();

entries.css:
/* CV9 · טופס שמתקן בעדינות */
.cx *{box-sizing:border-box}
.cx{--cx-err:color-mix(in srgb,#d23b22 72%,var(--ink, #16182b));font-size:16px;line-height:1.6;color:var(--ink, #16182b)}
.cx :where(a){color:inherit}
.cx :where(h2,h3){text-wrap:balance}
.cx :where(p,small,li){text-wrap:pretty}
.cx :focus-visible{outline:2px solid var(--accent, #4a3aff);outline-offset:3px;border-radius:8px}
.cx-btn{position:relative;display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:52px;padding:0 24px;border:0;border-radius:14px;
  background:var(--accent, #4a3aff);color:var(--accent-ink, #fff);font:inherit;font-size:16px;font-weight:600;text-decoration:none;cursor:pointer;white-space:nowrap;
  transition:transform .18s cubic-bezier(.2,.6,.2,1),background .2s cubic-bezier(.2,.6,.2,1),box-shadow .2s cubic-bezier(.2,.6,.2,1)}
.cx-btn svg{width:20px;height:20px;flex:none}
.cx-btn:active{transform:scale(.97)}
.cx-btn.is-ghost{background:transparent;color:var(--ink, #16182b);box-shadow:inset 0 0 0 1.5px color-mix(in srgb,var(--ink, #16182b) 22%,transparent)}
@media (hover:hover) and (pointer:fine){.cx-btn:hover{transform:translateY(-1px)}.cx-btn.is-ghost:hover{box-shadow:inset 0 0 0 1.5px var(--ink, #16182b)}
  .cx a:hover .ic-arr,.cx-btn:hover .ic-arr{transform:translateX(-4px)}}
.ic-arr{transition:transform .2s cubic-bezier(.2,.6,.2,1)}
[dir="ltr"] .ic-arr{rotate:180deg}
.cx-rv{opacity:0;transform:translateY(16px);transition:opacity .5s cubic-bezier(.2,.6,.2,1),transform .5s cubic-bezier(.2,.6,.2,1);transition-delay:calc(var(--i,0) * 80ms)}
.is-in .cx-rv{opacity:1;transform:none}
/* a time or a phone number never breaks between rows ("050-000" on one, "0000" on the next, at 500) */
.cx-t{unicode-bidi:isolate;font-variant-numeric:tabular-nums;white-space:nowrap}
/* the demo switch: lets the reviewer see every state. Not part of the component you copy. */
.cx-demo{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:0 0 24px;padding:6px;border-radius:14px;background:color-mix(in srgb,var(--ink, #16182b) 5%,transparent);font-size:13px;width:max-content;max-width:100%}
.cx-demo > span{padding:0 10px;font-weight:600;color:var(--muted, #6a6d85)}
.cx-demo button{min-height:36px;padding:0 14px;border:0;border-radius:10px;background:none;font:inherit;font-weight:600;color:var(--ink, #16182b);cursor:pointer;transition:background .18s cubic-bezier(.2,.6,.2,1),color .18s cubic-bezier(.2,.6,.2,1)}
.cx-demo button[aria-pressed="true"]{background:var(--card, #fff);box-shadow:0 1px 3px color-mix(in srgb,var(--ink, #16182b) 14%,transparent)}
.cx-demo input{min-height:36px;padding:0 12px;border:0;border-radius:10px;background:var(--card, #fff);font:inherit;font-size:14px;color:var(--ink, #16182b);width:220px}
@media (prefers-reduced-motion:reduce){.cx *,.cx *::before,.cx *::after{transition-duration:.01ms!important;transition-delay:0s!important;animation-duration:.01ms!important;animation-iteration-count:1!important}.cx-rv{opacity:1;transform:none}}
.cxw{margin-inline:var(--gutter, clamp(24px, 5vw, 96px));border-radius:var(--r, 14px);background:var(--bg, #f7f7fa);box-shadow:0 0 0 1px var(--line, #e4e4ee);overflow:hidden;isolation:isolate}
.cxw-in{max-width:640px;margin-inline:auto;padding:72px 24px 88px}
@media (max-width:700px){.cxw-in{padding:48px 20px 64px}}
.g9-h{margin:0 0 8px;font-size:clamp(26px,3.4vw,36px);line-height:1.15;font-weight:700}
.g9-sub{margin:0 0 28px;color:var(--muted, #6a6d85)}
.g9 form{display:grid;gap:20px}
.g9-sum{display:grid;grid-template-rows:0fr;transition:grid-template-rows .35s cubic-bezier(.2,.6,.2,1)}
.g9-sum.is-open{grid-template-rows:1fr}
.g9-sum > div{overflow:hidden;min-height:0}
.g9-sum-in{margin-bottom:4px;padding:16px 20px;border-radius:16px;background:color-mix(in srgb,var(--cx-err) 7%,var(--bg, #f7f7fa))}
.g9-sum:focus{outline:0}
/* the ring is drawn inside the box: an outline would be clipped by the row track that opens it */
.g9-sum:focus-visible .g9-sum-in{box-shadow:inset 0 0 0 2px color-mix(in srgb,var(--cx-err) 45%,transparent)}
.g9-sum b{display:block;margin-bottom:6px;color:var(--cx-err)}
.g9-sum ul{margin:0;padding-inline-start:20px}
.g9-sum a{font-size:15px;text-underline-offset:3px}
.g9-f label{display:block;margin-bottom:8px;font-size:14px;font-weight:600}
.g9-in{position:relative}
.g9-f input{width:100%;min-height:52px;padding:0 16px;padding-inline-end:48px;border:0;border-radius:14px;background:var(--card, #fff);font:inherit;color:var(--ink, #16182b);
  box-shadow:inset 0 0 0 1.5px color-mix(in srgb,var(--ink, #16182b) 12%,transparent);transition:box-shadow .18s cubic-bezier(.2,.6,.2,1)}
.g9-f input:focus{outline:0;box-shadow:inset 0 0 0 2px var(--accent, #4a3aff)}
/* an LTR field (phone, mail) starts on the left, where the tick sits in an RTL page: move the room to its start */
.g9-f input[dir="ltr"]{padding-inline:48px 16px}
.g9-f.is-bad input{box-shadow:inset 0 0 0 2px color-mix(in srgb,var(--cx-err) 70%,transparent)}
.g9-f.is-bad input:focus{box-shadow:inset 0 0 0 2px var(--cx-err)}
/* a quiet tick at the end of a field that became right: the reward comes early, the error comes late */
.g9-tick{position:absolute;inset-inline-end:14px;top:50%;width:20px;height:20px;margin-top:-10px;color:var(--accent, #4a3aff);opacity:0;transition:opacity .2s cubic-bezier(.2,.6,.2,1)}
.g9-tick path{stroke-dasharray:24;stroke-dashoffset:24;transition:stroke-dashoffset .3s cubic-bezier(.2,.6,.2,1) .05s}
.g9-f.is-ok .g9-tick{opacity:1}
.g9-f.is-ok .g9-tick path{stroke-dashoffset:0}
.g9-err,.g9-sug{display:grid;grid-template-rows:0fr;transition:grid-template-rows .28s cubic-bezier(.2,.6,.2,1)}
.g9-err > p,.g9-sug > div{overflow:hidden;min-height:0;margin:0}
.g9-f.is-bad .g9-err,.g9-sug.is-open{grid-template-rows:1fr}
.g9-err p{display:flex;gap:8px;align-items:flex-start;padding-top:8px;font-size:14px;line-height:1.45;color:var(--cx-err)}
.g9-err svg{width:16px;height:16px;flex:none;margin-top:1px}
.g9-sug button{display:inline-flex;align-items:center;gap:6px;min-height:44px;margin-top:8px;padding:0 14px;border:0;border-radius:999px;background:color-mix(in srgb,var(--accent, #4a3aff) 10%,transparent);
  font:inherit;font-size:14px;color:var(--ink, #16182b);cursor:pointer;transition:background .18s cubic-bezier(.2,.6,.2,1)}
.g9-sug button b{direction:ltr;unicode-bidi:isolate;color:var(--accent, #4a3aff)}
@media (hover:hover) and (pointer:fine){.g9-sug button:hover{background:color-mix(in srgb,var(--accent, #4a3aff) 18%,transparent)}}
.g9 .cx-btn{justify-self:start}
.g9-done{display:none;padding:20px;border-radius:16px;background:color-mix(in srgb,var(--accent, #4a3aff) 9%,var(--bg, #f7f7fa));font-weight:600}
/* focus lands here only so the confirmation is read out: it is a message, not a control, so no ring */
.cx .g9-done:focus,.cx .g9-done:focus-visible{outline:0}
.g9.is-sent form{display:none}
.g9.is-sent .g9-done{display:block;animation:g9-in .4s cubic-bezier(.2,.6,.2,1)}
@keyframes g9-in{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}

