/* מחלקות עזר של המאגר שהרכיב הזה משתמש בהן */
.stage{padding:var(--sec, clamp(120px, 12vw, 260px)) var(--gutter, clamp(24px, 5vw, 96px));position:relative}
.stage.tight{padding-block:clamp(48px,5vw,90px)}
.stage.full{padding-inline:0}

/* B70 · כפתור שיתוף שנפרש */
.sh{max-width:min(760px,94vw);margin-inline:auto;display:grid;gap:clamp(24px,3vw,40px)}
.sh-post{padding:clamp(24px,3vw,48px);border-radius:24px;background:var(--card, #fff);box-shadow:0 24px 48px -32px color-mix(in srgb,var(--ink, #16182b) 40%,transparent)}
.sh-k{margin:0 0 12px;font-size:14px;font-weight:600;color:var(--muted, #6a6d85)}
.sh-post h3{margin:0 0 12px;font-size:clamp(24px,2.2vw,34px);line-height:1.2}
.sh-post p{margin:0;color:var(--muted, #6a6d85);line-height:1.6}
.sh-row{display:flex;flex-wrap:wrap;align-items:center;gap:16px;margin-top:32px}
.shr{position:relative;display:flex;flex-wrap:wrap;align-items:center;gap:12px}
.shr-btn{position:relative;display:inline-flex;align-items:center;gap:10px;height:48px;padding:0 20px;border:0;border-radius:999px;background:var(--ink, #16182b);color:var(--bg, #f7f7fa);font:inherit;font-weight:700;cursor:pointer;
  transition:transform .2s cubic-bezier(.2,.6,.2,1)}
@media (hover:hover) and (pointer:fine){.shr-btn:hover{transform:translateY(-2px)}}
.shr-btn:focus-visible,.shr-it:focus-visible{outline:2px solid var(--accent, #4a3aff);outline-offset:3px}
.shr-btn svg{flex:none;width:20px;height:20px;transition:transform .35s cubic-bezier(.76,0,.24,1),opacity .2s}
.shr-x{position:absolute;inset-inline-start:14px;opacity:0;transform:rotate(-90deg)}
.shr.open .shr-ic{opacity:0;transform:rotate(90deg)}
.shr.open .shr-x{opacity:1;transform:none}
.shr-list{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.shr-list[hidden]{display:none} /* סגורה לא תופסת מקום: בלי זה נשאר חור של שורת עיגולים שקופה */
.shr-list li{position:relative;opacity:0;transform:translateX(24px);transition:opacity .15s,transform .15s}
.shr.open .shr-list li{opacity:1;transform:none;transition:opacity .3s calc(var(--i) * 50ms),transform .45s calc(var(--i) * 50ms) cubic-bezier(.2,.6,.2,1)}
.shr-it{display:grid;place-items:center;width:44px;height:44px;padding:0;border:0;border-radius:50%;background:color-mix(in srgb,var(--ink, #16182b) 7%,transparent);color:var(--ink, #16182b);cursor:pointer;
  transition:background-color .25s,color .25s,transform .25s cubic-bezier(.2,.6,.2,1)}
.shr-it svg{width:20px;height:20px}
/* צבע הרשת בריחוף. וואטסאפ בגוון הכהה שלו: הירוק הבהיר עם אייקון לבן לא עובר ניגודיות */
@media (hover:hover) and (pointer:fine){.shr-it:hover{background:var(--c);color:#fff;transform:translateY(-3px)} /* qa-allow: white, אייקון לבן על צבע רשת קבוע */}
.shr-it:focus-visible{background:var(--c);color:#fff}
.shr-it.me:hover,.shr-it.me:focus-visible,.shr-it.me.done{background:var(--ink, #16182b);color:var(--bg, #f7f7fa)}
.shr-it.done{background:var(--c);color:#fff}
.shr-tip{position:absolute;left:50%;bottom:calc(100% + 10px);translate:-50% 0;white-space:nowrap;padding:6px 10px;border-radius:8px;background:var(--ink, #16182b);color:var(--bg, #f7f7fa);font-size:13px;
  opacity:0;transform:translateY(4px);pointer-events:none;transition:opacity .2s,transform .2s}
.shr-it:hover+.shr-tip,.shr-it:focus-visible+.shr-tip{opacity:1;transform:none}
.shr-c .shr-btn{width:48px;padding:0;justify-content:center}
.shr-c .shr-lbl{display:none}
.shr-c .shr-x{inset-inline-start:auto}
.sh-note{margin:0;font-size:14px;color:var(--muted, #6a6d85);min-height:20px}
.sh-alt{display:flex;align-items:center;gap:16px;color:var(--muted, #6a6d85);font-size:15px}
@media (prefers-reduced-motion: reduce){.shr-list li,.shr.open .shr-list li,.shr-btn svg,.shr-it,.shr-tip{transition-duration:.01ms;transition-delay:0s}}

