      el.style.setProperty("--sf-s",size*clamp(pos/reveal)+"px");
      el.style.setProperty("--sf-e",size*clamp((max-pos)/reveal)+"px");
    }
    el.addEventListener("scroll",sync,{passive:true});addEventListener("resize",sync);sync();
  });
})();

