if (typeof gsap !== "undefined") gsap.registerPlugin(ScrollTrigger);

(function(){
  // בלי הספרייה, או בלי ScrollTrigger, הסקשנים נשארים זורמים: אין .is-stack ולכן אין הדבקה, ושום דבר לא מוסתר
  if(typeof gsap==="undefined"||typeof ScrollTrigger==="undefined")return;
  const root=document.querySelector(".sk"),panels=gsap.utils.toArray(".sk-panel",root);
  // בהפחתת תנועה הפונקציה לא רצה: הערימה לא מופעלת והסקשנים זורמים כרגיל. בסיבוב טאבלט matchMedia מחליף גרסה
  gsap.matchMedia().add("(prefers-reduced-motion: no-preference)",()=>{
    root.classList.add("is-stack");
    // גובה כל סקשן למשתנה, וה-CSS מחשב ממנו את נקודת ההדבקה (100dvh פחות הגובה). offsetHeight לא מושפע מהכיווץ
    const measure=()=>panels.forEach(p=>p.style.setProperty("--sk-h",p.offsetHeight+"px"));
    measure();
    ScrollTrigger.addEventListener("refreshInit",measure);
    // פונט שנטען או שורה שנשברת אחרת משנים גובה בלי אירוע resize: מודדים ומרעננים את הטריגרים
    let raf=0;
    const ro=new ResizeObserver(()=>{cancelAnimationFrame(raf);raf=requestAnimationFrame(()=>{measure();ScrollTrigger.refresh();});});
    panels.forEach(p=>ro.observe(p));
    // הסקשן נסוג בדיוק בזמן שהבא עולה מעליו, ולכן הטריגר הוא הבא ולא הנוכחי. הנסיגה לא מתחילה לפני שהבא נכנס,
    // ובסקשן גבוה הבא נכנס רק אחרי מרווח המנוחה, כלומר אחרי שהתחתית נראתה
    panels.slice(0,-1).forEach((p,i)=>{
      gsap.fromTo(p,{"--sk-s":1,"--sk-dim":0},{"--sk-s":.92,"--sk-dim":.55,ease:"none",
        scrollTrigger:{trigger:panels[i+1],start:"top bottom",end:"top top",scrub:.4}});
    });
    return()=>{
      ScrollTrigger.removeEventListener("refreshInit",measure);ro.disconnect();cancelAnimationFrame(raf);
      root.classList.remove("is-stack");
      panels.forEach(p=>{p.style.removeProperty("--sk-h");p.style.removeProperty("--sk-s");p.style.removeProperty("--sk-dim");});
    };
  });
})();

entries.css:
/* מחלקות עזר של המאגר שהרכיב הזה משתמש בהן */
.stage{padding:var(--sec, clamp(120px, 12vw, 260px)) var(--gutter, clamp(24px, 5vw, 96px));position:relative}
.stage.tight{padding-block:clamp(48px,5vw,90px)}
.stage.full{padding-inline:0}

/* G160 · ענן נקודות שמתכנס לגרף */
.sw{position:relative;max-width:1100px;margin-inline:auto}
.sw-pin{display:grid;gap:clamp(24px,4vw,48px);padding-block:clamp(24px,4vw,64px)}
.sw-top{position:relative;z-index:1;display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:24px 48px}
.sw-head{display:grid;gap:12px;max-width:44ch}
.sw-head h2{margin:0;font-size:clamp(28px,3.4vw,48px);line-height:1.12;text-wrap:balance}
.sw-head p{margin:0;color:var(--muted, #6a6d85);font-size:var(--fs-body, clamp(17px, 0.6vw + 0.7rem, 22px));line-height:1.6}
.sw-count{display:flex;align-items:baseline;gap:12px;margin:0;font-size:clamp(56px,8vw,112px);font-weight:700;line-height:.9;letter-spacing:-.02em;font-variant-numeric:tabular-nums}
.sw-count small{font-size:max(.2em,16px);font-weight:500;letter-spacing:0;color:var(--muted, #6a6d85)}
.sw .sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.sw-fig{position:relative;margin:0;aspect-ratio:5 / 2}
/* הגרף הסטטי: אותו אזור שאליו הנקודות מתיישבות. בטלפון הוא יושב בתחתית ומעליו נשאר מקום לענן */
.sw-plot{position:absolute;inset:0}
.sw-svg{display:block;width:100%;height:100%;overflow:visible;transition:opacity .6s cubic-bezier(.2,.6,.2,1)}
.sw-svg:dir(ltr){transform:scaleX(-1)}
.sw-pd1 circle{fill:color-mix(in srgb,var(--ink, #16182b) 48%,transparent)}
.sw-pd2 circle{fill:var(--accent, #4a3aff)}
.sw-ln{stroke:var(--ink, #16182b);stroke-width:2;stroke-linejoin:round;vector-effect:non-scaling-stroke;opacity:.7}
.sw-ax{stroke:var(--line, #e4e4ee);stroke-width:1;vector-effect:non-scaling-stroke}
.sw-tag{position:absolute;left:33.3%;top:17.5%;translate:-50% calc(-100% - 10px);padding:6px 14px;border:1px solid var(--line, #e4e4ee);border-radius:999px;background:var(--card, #fff);color:var(--ink, #16182b);font-size:14px;font-weight:600;white-space:nowrap}
.sw-tag::after{content:"";position:absolute;left:50%;top:100%;height:10px;border-inline-start:1px solid var(--line, #e4e4ee)}
.sw-tag:dir(ltr){left:66.7%}
.sw-cv{position:absolute;left:-6%;top:-18%;width:112%;height:136%;pointer-events:none;opacity:0;transition:opacity .6s cubic-bezier(.2,.6,.2,1)}
.sw-fig.is-on .sw-cv{opacity:1}
.sw-fig.is-on .sw-svg{opacity:0}
/* המהלך רץ: הסקשן גבוה והבמה נעוצה במסך, והגלילה מקדמת את הנקודות */
.sw.is-live{height:260vh}
.sw.is-live .sw-pin{position:sticky;top:0;height:100vh;height:100svh;align-content:center;overflow:hidden}
@media(prefers-reduced-motion:reduce){.sw-svg,.sw-cv{transition:none}}
@media(max-width:767px){
  .sw-top{gap:16px}
  .sw.is-live .sw-fig{aspect-ratio:1 / 1}
  .sw.is-live .sw-plot{inset:auto 0 0 0;aspect-ratio:5 / 2}
  .sw.is-live .sw-cv{left:0;width:100%}
}

