      W=cr.width;H=cr.height;cv.width=Math.round(W*dpr);cv.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);
      PL=pr.left-cr.left;PT=pr.top-cr.top;PW=pr.width;PH=pr.height;
