.mb{display:grid;gap:24px;justify-items:center;text-align:center;padding:clamp(48px,6vw,96px) var(--gutter, clamp(24px, 5vw, 96px))}
.mb-k{margin:0;font-size:15px;font-weight:600;color:var(--muted, #6a6d85)}
.mb-field{position:relative;isolation:isolate;container-type:size;display:grid;place-items:center;width:100%;height:clamp(320px,60vh,600px)}
.mb-word{margin:0;font-size:clamp(80px,22cqw,300px);font-weight:800;line-height:1;letter-spacing:-.02em;white-space:nowrap}
.mb-base{position:relative;z-index:1;color:var(--ink, #16182b)}
.mb-art{--s:min(50cqw,86cqh);position:absolute;inset:0;pointer-events:none}
.mb-blob{position:absolute;z-index:2;left:calc(50% - var(--s)/2);top:calc(50% - var(--s)/2);width:var(--s);height:var(--s);overflow:hidden;background:var(--accent, #4a3aff);border-radius:58% 42% 61% 39% / 46% 55% 45% 54%;transform:translate(calc(var(--s)*-.14),calc(var(--s)*-.05)) rotate(0deg);animation:mb-blob 18s cubic-bezier(.4,0,.2,1) infinite alternate}
/* העותק ההפוך: בגודל המסגרת, מוזז כך שמרכזו במרכז המסגרת, ורץ בתנועה ההופכית לכתם */
.mb-in{position:absolute;left:calc(var(--s)/2 - 50cqw);top:calc(var(--s)/2 - 50cqh);width:100cqw;height:100cqh;display:grid;place-items:center;transform:rotate(0deg) translate(calc(var(--s)*.14),calc(var(--s)*.05));animation:mb-inner 18s cubic-bezier(.4,0,.2,1) infinite alternate}
.mb-in .mb-word{color:var(--accent-ink, #fff)}
.mb-ring{position:absolute;z-index:0;width:calc(var(--s)*var(--g));height:calc(var(--s)*var(--g));left:calc(50% - var(--s)*var(--g)/2);top:calc(50% - var(--s)*var(--g)/2);border:1px solid color-mix(in srgb,var(--accent, #4a3aff) 55%,transparent);border-radius:58% 42% 61% 39% / 46% 55% 45% 54%;transform:translate(calc(var(--s)*-.14),calc(var(--s)*-.05)) rotate(0deg);animation:mb-blob 18s cubic-bezier(.4,0,.2,1) infinite alternate;animation-delay:var(--o)}
.mb-ring.r1{--g:1.12;--o:-4s}
.mb-ring.r2{--g:1.24;--o:-8s}
