/* מחלקות עזר של המאגר שהרכיב הזה משתמש בהן */
.stage{padding:var(--sec, clamp(120px, 12vw, 260px)) var(--gutter, clamp(24px, 5vw, 96px));position:relative}
.stage.tight{padding-block:clamp(48px,5vw,90px)}
.stage.full{padding-inline:0}

/* G161 · קו אות שהופך לדופק וגלים */
.sg{position:relative;max-width:1100px;margin-inline:auto}
.sg-pin{display:grid;gap:clamp(24px,3vw,40px);padding-block:clamp(24px,4vw,64px)}
.sg-head{display:grid;gap:12px;max-width:52ch}
.sg-head h2{margin:0;font-size:clamp(28px,3.4vw,48px);line-height:1.12;text-wrap:balance}
.sg-head p{margin:0;color:var(--muted, #6a6d85);font-size:var(--fs-body, clamp(17px, 0.6vw + 0.7rem, 22px));line-height:1.6}
.sg-fig{margin:0;display:grid;gap:12px}
.sg-plot{position:relative;height:clamp(200px,40svh,360px)}
.sg-svg{position:absolute;inset:0;display:block;width:100%;height:100%;overflow:visible}
.sg-glow{filter:drop-shadow(0 0 8px color-mix(in srgb,var(--accent, #4a3aff) 50%,transparent))}
.sg-svg:dir(ltr){transform:scaleX(-1)}
.sg-grid{fill:none;stroke:var(--line, #e4e4ee);stroke-width:1;vector-effect:non-scaling-stroke}
.sg-line{fill:none;stroke:var(--accent, #4a3aff);stroke-width:2.5;stroke-linejoin:round;stroke-linecap:round;vector-effect:non-scaling-stroke}
.sg-thr{position:absolute;inset-inline:0;top:30%;border-top:1px dashed color-mix(in srgb,var(--ink, #16182b) 30%,transparent);pointer-events:none}
.sg-thr span{position:absolute;inset-inline-start:0;bottom:6px;font-size:13px;color:var(--muted, #6a6d85)}
.sg-dot{position:absolute;left:50%;top:60%;width:12px;height:12px;border-radius:50%;background:var(--accent, #4a3aff);box-shadow:0 0 0 6px color-mix(in srgb,var(--accent, #4a3aff) 22%,transparent);transform:translate(-50%,-50%)}
