.sg-ticks{display:flex;justify-content:space-between;font-size:13px;color:var(--muted, #6a6d85);font-variant-numeric:tabular-nums}
.sg-caps{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:24px}
