.sh-pin{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);align-items:center;gap:clamp(24px,5vw,72px);padding-block:clamp(24px,4vw,64px)}
.sh-copy{display:grid;gap:16px;justify-items:start;max-width:40ch}
.sh-k{margin:0;font-size:15px;font-weight:600;color:var(--muted, #6a6d85)}
.sh h2{margin:0;font-size:clamp(30px,3.8vw,52px);line-height:1.1;text-wrap:balance}
.sh-lead{margin:0;font-size:var(--fs-body, clamp(17px, 0.6vw + 0.7rem, 22px));line-height:1.6;color:var(--muted, #6a6d85)}
.sh-link{display:inline-flex;align-items:center;padding:14px 28px;border-radius:999px;border:1px solid var(--line, #e4e4ee);background:var(--card, #fff);color:var(--ink, #16182b);font-weight:700;text-decoration:none;transition:transform .2s cubic-bezier(.2,.6,.2,1)}
@media (hover:hover) and (pointer:fine){.sh-link:hover{transform:translateY(-2px)}}
.sh-link:focus-visible{outline:2px solid var(--ink, #16182b);outline-offset:3px}
.sh-fig{margin:0;display:grid;justify-items:center}
.sh-svg{display:block;width:min(100%,440px);height:auto;max-height:76svh;overflow:visible;filter:drop-shadow(0 0 calc(var(--gl,1) * 18px) color-mix(in srgb,var(--accent, #4a3aff) calc(var(--gl,1) * 45%),transparent))}
.sh-f{color:color-mix(in srgb,var(--accent, #4a3aff) calc((.45 + var(--k) * .55) * 100%),var(--bg, #f7f7fa));fill:currentColor;stroke:currentColor;stroke-width:.8;stroke-linejoin:round}
.sh-wire{opacity:0}
.sh-wire path{fill:none;stroke:var(--ink, #16182b);stroke-width:1;vector-effect:non-scaling-stroke}
.sh-wire circle{fill:var(--ink, #16182b)}
.sh-ground{fill:none;stroke:var(--line, #e4e4ee);stroke-width:1;vector-effect:non-scaling-stroke}
/* המהלך רץ: הסקשן גבוה והבמה נעוצה במסך, והשרטוט מופיע עד שהפאות נכנסות */
.sh.is-live{height:300vh}
.sh.is-live .sh-pin{position:sticky;top:0;height:100vh;height:100svh;overflow:hidden}
.sh.is-live .sh-wire{opacity:.65}
@media(prefers-reduced-motion:reduce){.sh-link{transition:none}}
@media(max-width:767px){
  .sh-pin{grid-template-columns:minmax(0,1fr);gap:16px;align-content:center}
  .sh-svg{max-height:44svh}
}

