.sr{position:relative;max-width:1100px;margin-inline:auto}
.sr-pin{display:grid;align-content:center;gap:clamp(16px,2.4vw,32px);padding-block:clamp(16px,3vw,48px)}
.sr-k{margin:0;text-align:center;font-size:15px;font-weight:600;color:var(--muted, #6a6d85)}
