.sr-sun{position:absolute;left:50%;margin-left:calc(var(--d) / -2);bottom:calc(var(--d) * .12);width:var(--d);aspect-ratio:1;border-radius:50%;background:radial-gradient(circle at 50% 38%,color-mix(in srgb,var(--accent, #4a3aff) 22%,var(--bg, #f7f7fa)),color-mix(in srgb,var(--accent, #4a3aff) 44%,var(--bg, #f7f7fa)))}
