.sr-w{display:inline-block}
.sr-ground{display:grid;gap:16px;justify-items:center;text-align:center}
.sr-lead{margin:0;max-width:52ch;font-size:var(--fs-body, clamp(17px, 0.6vw + 0.7rem, 22px));line-height:1.6;color:var(--muted, #6a6d85)}
