if (typeof gsap !== "undefined") gsap.registerPlugin(ScrollTrigger);

(function(){
  if(typeof gsap==="undefined")return;      // בלי GSAP נשארת השמש מעל הקו והכותרת המלאה
  const root=document.querySelector(".sr"),sun=root.querySelector(".sr-sun"),halo=root.querySelector(".sr-halo"),
    gr=root.querySelector(".sr-ground"),words=[].slice.call(root.querySelectorAll(".sr-w"));
  gsap.matchMedia().add("(prefers-reduced-motion: no-preference)",()=>{
    root.classList.add("is-live");
    // השמש והמילים מוזזות רק ב-yPercent: הקצה התחתון של קופסת השמיים הוא קו האופק והוא חותך כל מה שמתחתיו
    const tl=gsap.timeline({scrollTrigger:{trigger:root,start:"top top",end:"bottom bottom",scrub:.6,invalidateOnRefresh:true}});
    tl
      .fromTo(sun,{yPercent:112,scale:.78},{yPercent:0,scale:1,duration:.78,ease:"power1.out"},0)
      .fromTo(halo,{opacity:0},{opacity:1,duration:.5,ease:"none"},.3)
      .fromTo(gr,{autoAlpha:0,y:24},{autoAlpha:1,y:0,duration:.2,ease:"power2.out"},.72);
    // כל מילה בטווח משלה (ולא stagger): כך שכל המילים מוסתרות מתחת לאופק כבר בטעינה
    words.forEach((w,i)=>tl.fromTo(w,{yPercent:115},{yPercent:0,duration:.3,ease:"power3.out"},.3+i*.1));
    return()=>{gsap.set([sun,halo,gr].concat(words),{clearProps:"all"});root.classList.remove("is-live");};
  });
})();

entries.css:
/* מחלקות עזר של המאגר שהרכיב הזה משתמש בהן */
.stage{padding:var(--sec, clamp(120px, 12vw, 260px)) var(--gutter, clamp(24px, 5vw, 96px));position:relative}
.stage.tight{padding-block:clamp(48px,5vw,90px)}
.stage.full{padding-inline:0}

/* G180 · סמן מתוסרט שמפעיל ממשק דוגמה */
.sc{--sx:-1;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.05fr);align-items:center;gap:clamp(32px,6vw,96px);max-width:1040px;margin-inline:auto}
.sc-txt{display:grid;gap:14px;max-width:36ch}
.sc-txt h3{margin:0;font-size:clamp(26px,2.6vw,40px);line-height:1.15;text-wrap:balance}
.sc-txt p{margin:0;color:var(--muted, #6a6d85);font-size:var(--fs-body, clamp(17px, 0.6vw + 0.7rem, 22px));line-height:1.6}
.sc-win{position:relative;justify-self:center;box-sizing:border-box;width:min(460px,100%);background:var(--card, #fff);border:1px solid var(--line, #e4e4ee);border-radius:18px;box-shadow:0 28px 56px -32px color-mix(in srgb,var(--ink, #16182b) 40%,transparent)}
.sc-bar{display:flex;align-items:center;gap:8px;padding:14px 18px;border-bottom:1px solid var(--line, #e4e4ee)}
.sc-bar i{width:10px;height:10px;border-radius:50%;background:var(--line, #e4e4ee)}
.sc-ttl{margin-inline-start:12px;font-size:13px;color:var(--muted, #6a6d85)}
.sc-body{display:grid;gap:12px;padding:20px}
.sc-opt{display:flex;align-items:center;gap:14px;padding:12px 14px;border:1px solid var(--line, #e4e4ee);border-radius:12px;font-size:15px;line-height:1.3}
.sc-tg{flex:none;display:flex;align-items:center;box-sizing:border-box;width:40px;height:24px;padding:4px;border-radius:999px;background:var(--line, #e4e4ee);transition:background-color .3s cubic-bezier(.2,.6,.2,1)}
.sc-tg i{width:16px;height:16px;border-radius:50%;background:var(--muted, #6a6d85);transition:transform .3s cubic-bezier(.2,.6,.2,1),background-color .3s cubic-bezier(.2,.6,.2,1)}
.sc-opt.is-on .sc-tg{background:var(--accent, #4a3aff)}
.sc-opt.is-on .sc-tg i{background:var(--accent-ink, #fff);transform:translateX(calc(var(--sx) * 16px))}
.sc-in{display:grid;gap:6px}
.sc-lbl{font-size:13px;color:var(--muted, #6a6d85)}
.sc-val{display:flex;align-items:center;min-height:44px;padding:0 14px;border:1px solid var(--line, #e4e4ee);border-radius:12px;font-size:15px;transition:border-color .25s linear}
.sc-in.is-focus .sc-val{border-color:var(--accent, #4a3aff)}
.sc-caret{flex:none;width:2px;height:20px;margin-inline-start:4px;background:var(--accent, #4a3aff);opacity:0}
.sc-in.is-typing .sc-caret{opacity:1;animation:sc-blink 1s steps(1) infinite}
@keyframes sc-blink{50%{opacity:0}}
.sc-go{display:grid;place-items:center;min-height:48px;padding:0 20px;border-radius:12px;background:var(--line, #e4e4ee);color:var(--ink, #16182b);font-size:16px;font-weight:600;transition:background-color .3s cubic-bezier(.2,.6,.2,1)}
.sc-go>span{grid-area:1/1;transition:opacity .25s linear}
.sc-go-b{opacity:0;color:var(--accent-ink, #fff)}
.sc-go.is-on{background:var(--accent, #4a3aff)}
