/* G181 · שדה שמקליד שאלה ומחזיר תשובה */
@property --qf-ang{syntax:"<angle>";inherits:true;initial-value:0deg}
.qf{--qf-ring:conic-gradient(from var(--qf-ang),var(--accent, #4a3aff),color-mix(in srgb,var(--accent, #4a3aff) 55%,var(--card, #fff)),color-mix(in srgb,var(--accent, #4a3aff) 82%,var(--ink, #16182b)),color-mix(in srgb,var(--accent, #4a3aff) 40%,var(--card, #fff)),var(--accent, #4a3aff));display:grid;gap:32px;max-width:680px;margin-inline:auto}
@media(prefers-reduced-motion:no-preference){.qf-field{animation:qf-spin 7s linear infinite}}
