.fp-ft{display:flex;gap:3em;padding:3em;background:color-mix(in srgb,var(--ink, #16182b) 5%,var(--card, #fff));color:var(--muted, #6a6d85)}
.fp-ft b{margin-inline-end:auto;color:var(--ink, #16182b);font-size:1.4em}
.fp-dof{position:absolute;inset-inline:0;bottom:0;height:34%;pointer-events:none;background:linear-gradient(to top,var(--bg, #f7f7fa),transparent);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);-webkit-mask-image:linear-gradient(to top,black 15%,transparent);mask-image:linear-gradient(to top,black 15%,transparent)}
.fp-fade{position:absolute;inset-inline:0;top:0;height:30%;pointer-events:none;opacity:0;background:linear-gradient(to bottom,var(--bg, #f7f7fa) 12%,transparent)}
