.fp-ico.i2{inset-inline-end:8%;top:16%}
.fp-ico.i3{inset-inline-start:14%;bottom:20%}
.fp-ico.i4{inset-inline-end:12%;bottom:26%}
.fp.is-live .fp-ico{animation:fp-float 6s cubic-bezier(.4,0,.2,1) infinite alternate}
