        if(v+.09*Math.sin(x*.011+t*.8+j*.35)>th)ctx.rect(x,y,DC,DC);
        if(v+.09*Math.sin(x*.011-t*.6+j*.3+2)>th)ctx.rect(x,H-DC-y,DC,DC);
      }
    }
    ctx.fill();
