.ls{--ls-light:color-mix(in oklab,var(--accent, #4a3aff) 14%,white);display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);column-gap:clamp(32px,6vw,96px);max-width:1100px;margin-inline:auto}
