.ls-scene{--mw:clamp(40px,10cqw,72px);position:relative;overflow:hidden;isolation:isolate;container-type:size;width:min(100%,calc(80svh * 1.25));aspect-ratio:5/4;border-radius:28px;background:var(--ink, #16182b)}
