/* מחלקות עזר של המאגר שהרכיב הזה משתמש בהן */
.stage{padding:var(--sec, clamp(120px, 12vw, 260px)) var(--gutter, clamp(24px, 5vw, 96px));position:relative}
.stage.tight{padding-block:clamp(48px,5vw,90px)}
.stage.full{padding-inline:0}

/* CSS43 · פסי אזהרה אלכסוניים עם תיבת מילה */
.hz{max-width:1100px;margin-inline:auto}
.hz-band{--p:48.08px;position:relative;isolation:isolate;display:grid;place-items:center;overflow:hidden;min-height:clamp(320px,58vh,540px);padding:24px;border-radius:24px}
/* התזוזה (68px, -68px) היא בדיוק תקופה אחת של הפסים (96.16px) לאורך האלכסון, ולכן הלולאה חלקה */
