.tt-card{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:32px;padding:32px;border-radius:24px;background:var(--card, #fff);box-shadow:inset 0 0 0 1px var(--line, #e4e4ee)}
.tt-head{margin:0 0 24px}
.tt-head h3{margin:0 0 4px;font-size:clamp(20px,2.1vw,28px);font-weight:700;line-height:1.2}
.tt-sum{margin:0;color:var(--muted, #6a6d85);font-size:var(--fs-body, clamp(17px, 0.6vw + 0.7rem, 22px));font-variant-numeric:tabular-nums}
.tt-plot{position:relative;aspect-ratio:640 / 300;container-type:size}
.tt-svg{position:absolute;inset:0;width:100%;height:100%}
.tt-grid line{stroke:var(--line, #e4e4ee);stroke-width:1;vector-effect:non-scaling-stroke}
.tt-g0{stop-color:var(--accent, #4a3aff);stop-opacity:.22}.tt-g1{stop-color:var(--accent, #4a3aff);stop-opacity:0}
.tt-area{fill:url(#tt-fill)}
.tt-line{fill:none;stroke:var(--accent, #4a3aff);stroke-width:3;stroke-linecap:round;stroke-linejoin:round;vector-effect:non-scaling-stroke}
.tt-yl{position:absolute;top:var(--t);inset-inline-start:0;translate:0 -110%;color:var(--muted, #6a6d85);font-size:13px;font-variant-numeric:tabular-nums}
/* קו השיער, הנקודה והטולטיפ ממוקמים ביחידות הקונטיינר: --fx ו--fy הם שברים מ-0 עד 1 */
.tt-hair{position:absolute;left:0;top:0;bottom:0;width:1px;background:color-mix(in oklab,var(--ink, #16182b) 20%,transparent);translate:calc(var(--fx) * 100cqw) 0}
.tt-dot{position:absolute;left:0;top:0;width:14px;height:14px;border-radius:50%;background:var(--accent, #4a3aff);box-shadow:0 0 0 4px var(--card, #fff),0 0 0 8px color-mix(in oklab,var(--accent, #4a3aff) 26%,transparent);translate:calc(var(--fx) * 100cqw - 50%) calc(var(--fy) * 100cqh - 50%)}
.tt-tip{position:absolute;left:0;top:0;display:grid;gap:2px;padding:8px 14px;border-radius:12px;background:var(--ink, #16182b);color:var(--bg, #f7f7fa);white-space:nowrap;line-height:1.2;translate:clamp(0px, calc(var(--fx) * 100cqw - 50%), calc(100cqw - 100%)) 0}
.tt-tip b{font-size:18px;font-weight:700;font-variant-numeric:tabular-nums}
.tt-tip span{font-size:13px;opacity:.82}
.tt-ax{display:flex;justify-content:space-between;margin-top:12px;color:var(--muted, #6a6d85);font-size:13px;font-variant-numeric:tabular-nums}
/* עמודת האירועים: הכרטיס החדש למעלה. הגזירה מסתירה את הכרטיס בזמן שהוא נכנס מהקצה */
.tt-ev{overflow:clip;overflow-clip-margin:8px}
.tt-list{list-style:none;margin:0;padding:0;display:grid;gap:12px;align-content:start}
.tt-c{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:14px;padding:14px 16px;border-radius:16px;background:var(--bg, #f7f7fa);box-shadow:inset 0 0 0 1px var(--line, #e4e4ee)}
.tt-c b{display:block;font-size:16px}
.tt-c small{display:block;margin-top:2px;color:var(--muted, #6a6d85);font-size:14px;line-height:1.35}
.tt-c strong{font-size:17px;font-variant-numeric:tabular-nums}
.tt-av{display:block;width:44px;height:44px;border-radius:50%;object-fit:cover}
.tt-ic{display:grid;place-items:center;width:44px;height:44px;border-radius:50%;background:var(--accent, #4a3aff);color:var(--accent-ink, #fff)}
.tt-ic svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}
.tt .sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.tt.is-live .tt-run{height:320vh}
.tt.is-live .tt-pin{position:sticky;top:0;min-height:100vh;min-height:100svh;display:grid;align-content:center}
@media(max-width:767px){.tt-card{grid-template-columns:minmax(0,1fr);gap:24px;padding:20px}.tt-plot{aspect-ratio:640 / 400}.tt-tip b{font-size:16px}}

