.tb{--tb-pale:color-mix(in oklab,var(--ink, #16182b) 12%,var(--card, #fff));display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);align-items:center;gap:clamp(32px,6vw,96px);max-width:1040px;margin-inline:auto}
.tb-doc{padding:40px;border-radius:24px;background:var(--card, #fff);box-shadow:inset 0 0 0 1px var(--line, #e4e4ee)}
