.hm-leg i{flex:0 0 clamp(96px,12vw,160px);height:10px;border-radius:10px;background:linear-gradient(to left,var(--card, #fff),var(--accent, #4a3aff));box-shadow:0 0 0 1px var(--line, #e4e4ee)}
