.hm-base{position:absolute;left:calc(var(--p) * -3.85);top:calc(var(--p) * -6.35);width:calc(var(--p) * 7.7);height:calc(var(--p) * 12.7);border-radius:calc(var(--p) * .3);background:color-mix(in oklab,var(--line, #e4e4ee) 40%,var(--card, #fff));box-shadow:0 0 0 1px var(--line, #e4e4ee);transform:translateZ(-2px)}
