.s1{--c:color-mix(in oklab,var(--accent, #4a3aff) 45%,var(--card, #fff))}
.s2{--c:color-mix(in oklab,var(--ink, #16182b) 55%,var(--card, #fff))}
.dg-d{fill:var(--c);transition:fill .3s linear}
.dg-mid{position:absolute;inset:0;display:grid;place-content:center;gap:8px;text-align:center}
.dg-mid b{display:block;font-size:17cqw;line-height:1;font-weight:700;color:var(--accent, #4a3aff);font-variant-numeric:tabular-nums}
.dg-mid small{display:block;color:var(--muted, #6a6d85);font-size:clamp(14px,3.4cqw,18px);line-height:1.3}
