  .dg-head p{font-size:15px;line-height:1.5}
  .dg-ring{width:min(100%,42svh)}
  .dg-legend{gap:8px}
  .dg-row{gap:12px;font-size:16px}
  .dg-pc{font-size:28px}
}
@media(prefers-reduced-motion:reduce){.dg-d,.dg-row{transition:none}}

