/* מחלקות עזר של המאגר שהרכיב הזה משתמש בהן */
.stage{padding:var(--sec, clamp(120px, 12vw, 260px)) var(--gutter, clamp(24px, 5vw, 96px));position:relative}
.stage.tight{padding-block:clamp(48px,5vw,90px)}
.stage.full{padding-inline:0}

/* G255 · נרות מחירים שזורמים בזמן אמת */
.ca{--dn:color-mix(in oklab,var(--ink, #16182b) 55%,var(--card, #fff));max-width:1120px;margin-inline:auto;display:grid;gap:clamp(24px,4vw,48px)}
.ca .sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.ca-head{display:grid;gap:12px;max-width:54ch}
.ca-head h2{margin:0;font-size:clamp(28px,3.4vw,48px);line-height:1.12;text-wrap:balance}
.ca-head p{margin:0;color:var(--muted, #6a6d85);font-size:var(--fs-body, clamp(17px, 0.6vw + 0.7rem, 22px));line-height:1.6}
.ca-card{margin:0;padding:clamp(16px,2.4vw,32px);border-radius:24px;background:var(--card, #fff);box-shadow:0 0 0 1px var(--line, #e4e4ee);display:grid;gap:clamp(16px,2.4vw,32px)}
.ca-top{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:16px}
.ca-name{display:grid;gap:4px}
.ca-name b{font-size:clamp(18px,1.6vw,22px);line-height:1.25}
.ca-name small{color:var(--muted, #6a6d85);font-size:14px;line-height:1.4}
.ca-quote{display:flex;align-items:baseline;gap:12px;font-variant-numeric:tabular-nums}
.ca-big{font-size:clamp(48px,6.4vw,88px);font-weight:700;line-height:1;letter-spacing:-.02em}
.ca-cur{font-size:clamp(20px,2.4vw,32px);color:var(--muted, #6a6d85);font-weight:600}
.ca-chg{align-self:center;padding:6px 12px;border-radius:999px;font-size:15px;font-weight:700;font-variant-numeric:tabular-nums;background:color-mix(in oklab,var(--accent, #4a3aff) 14%,var(--card, #fff));color:var(--accent, #4a3aff)}
.ca-chg.is-dn{background:color-mix(in oklab,var(--ink, #16182b) 10%,var(--card, #fff));color:var(--ink, #16182b)}
/* אזור הגרף: ריפוד פיזי לציר המחיר (בצד ההתחלה) ולתווית (בצד הסוף), והקנבס החי יושב על כל התיבה */
