.ca-plot{position:relative;height:100%}
.ca-svg{display:block;width:100%;height:100%}
.ca-svg:dir(rtl){transform:scaleX(-1)}
.ca-gl{fill:none;stroke:var(--line, #e4e4ee);stroke-width:1;stroke-dasharray:2 6;vector-effect:non-scaling-stroke}
.ca-wk{fill:none;stroke-width:1.5;vector-effect:non-scaling-stroke}
.ca-wk.u{stroke:var(--accent, #4a3aff)}
.ca-wk.d{stroke:var(--dn)}
.ca-bd.u{fill:var(--accent, #4a3aff)}
.ca-bd.d{fill:var(--dn)}
.ca-dot{position:absolute;width:10px;height:10px;border-radius:50%;background:var(--accent, #4a3aff);box-shadow:0 0 0 2px var(--card, #fff),0 0 0 7px color-mix(in oklab,var(--accent, #4a3aff) 22%,transparent)}
.ca-ov{position:absolute;inset:0}
.ca-ax{position:absolute;inset-inline-start:0;translate:0 -50%;font-size:12px;color:var(--muted, #6a6d85);font-variant-numeric:tabular-nums}
.ca-tag{position:absolute;inset-inline-end:0;translate:0 -50%;padding:6px 8px;border-radius:8px;background:var(--accent, #4a3aff);color:var(--accent-ink, #fff);font-size:13px;font-weight:700;font-variant-numeric:tabular-nums}
.ca-cv{position:absolute;inset:0;width:100%;height:100%}
/* המהלך רץ: הקנבס מחליף את ה-SVG הסטטי */
.ca.is-live .ca-plot,.ca.is-live .ca-ov{display:none}
@media(max-width:767px){
  .ca-chart{height:clamp(220px,40svh,320px);padding-inline:32px 64px}
  .ca-tag{font-size:12px}
}

