      sync();
    }});
    return()=>{
      if(ticking){gsap.ticker.remove(tick);ticking=false;}
      if(zoomTw)zoomTw.kill();
      ro.disconnect();document.removeEventListener("visibilitychange",onVis);
      cv.remove();probe.remove();
