.dvm-mid{z-index:3}
.dvm-side{z-index:1;margin-top:32px}
.dvm-ph{box-sizing:border-box;width:var(--pw);aspect-ratio:9/19;padding:calc(var(--pw) * .03);border-radius:calc(var(--pw) * .16);background:var(--ink, #16182b);box-shadow:0 36px 64px -32px color-mix(in srgb,var(--ink, #16182b) 60%,transparent);container-type:inline-size}
.dvm-scr{position:relative;display:flex;flex-direction:column;gap:3.4cqw;height:100%;box-sizing:border-box;padding:5cqw 5cqw 6cqw;border-radius:13cqw;overflow:hidden;background:var(--bg, #f7f7fa);color:var(--ink, #16182b);text-align:start;font-size:6.2cqw;line-height:1.35}
.dvm-notch{align-self:center;flex:none;width:26cqw;height:4.6cqw;border-radius:3cqw;background:var(--ink, #16182b)}
