.pp-c7{--c1:color-mix(in oklab,var(--ink, #16182b) 78%,var(--accent, #4a3aff));--c2:var(--card, #fff)}
.pp-c8{--c1:color-mix(in oklab,var(--accent, #4a3aff) 48%,var(--ink, #16182b));--c2:var(--bg, #f7f7fa)}
