  const reduce=matchMedia("(prefers-reduced-motion: reduce)"),EASE="cubic-bezier(.2,.6,.2,1)";
  const fmt=n=>n.toFixed(1)+"%";
  let shown=D[2].v,raf=0,timers=[];
