    ln.setAttribute("d",s);
    root.style.setProperty("--k",k.toFixed(3));
    chips.forEach((c,i)=>{
      const l=at(G.us[i],k),ds=l.s-G.D*G.us[i],x=(G.T.x*ds+G.N.x*l.w)*.55,y=(G.T.y*ds+G.N.y*l.w)*.55;
      c.style.transform="translate("+x.toFixed(1)+"px,"+y.toFixed(1)+"px)";
    });
  }
