/* G155 · יציאה מתוך אות (מעבר לסקשן בצבע הפוך) */
.lz{position:relative;background:var(--ink, #16182b);color:var(--bg, #f7f7fa)}
.lz-lead{margin:0;padding:var(--sec, clamp(120px, 12vw, 260px)) var(--gutter, clamp(24px, 5vw, 96px));background:var(--bg, #f7f7fa);color:var(--ink, #16182b);font-size:clamp(32px, 4.4vw, 64px);font-weight:700;line-height:1.1;text-align:center;text-wrap:balance}
.lz-body{padding:var(--sec, clamp(120px, 12vw, 260px)) var(--gutter, clamp(24px, 5vw, 96px));display:grid;justify-items:center;gap:40px;text-align:center}
.lz-type{position:relative}
/* בלי letter-spacing: הוא מזיז את התיבה של האות ביחס לציור שלה על ה-canvas */
.lz-h{margin:0;font-size:clamp(40px, 9vw, 140px);font-weight:700;line-height:1.08;letter-spacing:0}
.lz-ln{display:block}
.lz-u{position:relative;display:inline-block}
