      G.W=pin.clientWidth; G.H=pin.clientHeight;
      G.w0=Math.min(G.W*.72,G.H*.62*GW/GH);                    // האות במנוחה: עד 72% מהרוחב ו-62% מהגובה
      G.x0=(G.W-G.w0)/2; G.y0=(G.H-G.w0*GH/GW)/2;
