      .fromTo(win,{autoAlpha:0},{autoAlpha:1,duration:.06},.3)                               // התמונה כבר שם, חתוכה לאות, מתחת למילוי
      .fromTo(ph,{scale:1.12},{scale:1,duration:.6},.3)
